def torch_causal_conv1d_update(
    hidden_states,
    conv_state,
    weight,
    bias=None,
    activation=None,
):
    _, hidden_size, seq_len = hidden_states.shape
    state_len = conv_state.shape[-1]

    hidden_states_new = torch.cat([conv_state, hidden_states], dim=-1).to(weight.dtype)
    conv_state.copy_(hidden_states_new[:, :, -state_len:])
    out = F.conv1d(hidden_states_new, weight.unsqueeze(1), bias, padding=0, groups=hidden_size)
    out = F.silu(out[:, :, -seq_len:])
    out = out.to(hidden_states.dtype)
    return out


def l2norm(x: torch.FloatTensor, dim: int = -1, eps: float = 1e-6):
    """This function is intended to align with the l2norm implementation in the FLA library."""
    inv_norm = torch.rsqrt((x * x).sum(dim=dim, keepdim=True) + eps)
    return x * inv_norm


def torch_chunk_gated_delta_rule(
    query,
    key,
    value,
    g,
    beta,
    chunk_size=64,
    initial_state=None,
    output_final_state=False,
    use_qk_l2norm_in_kernel=False,
):
    initial_dtype = query.dtype
    if use_qk_l2norm_in_kernel:
        query = l2norm(query, dim=-1, eps=1e-6)
        key = l2norm(key, dim=-1, eps=1e-6)
    query, key, value, beta, g = [
        x.transpose(1, 2).contiguous().to(torch.float32) for x in (query, key, value, beta, g)
    ]

    batch_size, num_heads, sequence_length, k_head_dim = key.shape
    v_head_dim = value.shape[-1]
    pad_size = (chunk_size - sequence_length % chunk_size) % chunk_size
    query = F.pad(query, (0, 0, 0, pad_size))
    key = F.pad(key, (0, 0, 0, pad_size))
    value = F.pad(value, (0, 0, 0, pad_size))
    beta = F.pad(beta, (0, pad_size))
    g = F.pad(g, (0, pad_size))
    total_sequence_length = sequence_length + pad_size
    scale = 1 / (query.shape[-1] ** 0.5)
    query = query * scale

    v_beta = value * beta.unsqueeze(-1)
    k_beta = key * beta.unsqueeze(-1)
    # reshape to chunks
    query, key, value, k_beta, v_beta = [
        x.reshape(x.shape[0], x.shape[1], -1, chunk_size, x.shape[-1]) for x in (query, key, value, k_beta, v_beta)
    ]
    g = g.reshape(g.shape[0], g.shape[1], -1, chunk_size)
    mask = torch.triu(torch.ones(chunk_size, chunk_size, dtype=torch.bool, device=query.device), diagonal=0)

    # chunk decay
    g = g.cumsum(dim=-1)
    decay_mask = ((g.unsqueeze(-1) - g.unsqueeze(-2)).tril().exp().float()).tril()
    attn = -((k_beta @ key.transpose(-1, -2)) * decay_mask).masked_fill(mask, 0)
    for i in range(1, chunk_size):
        row = attn[..., i, :i].clone()
        sub = attn[..., :i, :i].clone()
        attn[..., i, :i] = row + (row.unsqueeze(-1) * sub).sum(-2)
    attn = attn + torch.eye(chunk_size, dtype=attn.dtype, device=attn.device)
    value = attn @ v_beta
    k_cumdecay = attn @ (k_beta * g.exp().unsqueeze(-1))
    last_recurrent_state = (
        torch.zeros(batch_size, num_heads, k_head_dim, v_head_dim).to(value)
        if initial_state is None
        else initial_state.to(value)
    )
    core_attn_out = torch.zeros_like(value)
    mask = torch.triu(torch.ones(chunk_size, chunk_size, dtype=torch.bool, device=query.device), diagonal=1)

    # for each chunk
    for i in range(0, total_sequence_length // chunk_size):
        q_i, k_i, v_i = query[:, :, i], key[:, :, i], value[:, :, i]
        attn = q_i @ k_i.transpose(-1, -2) * decay_mask[:, :, i]
        v_prime = (k_cumdecay[:, :, i]) @ last_recurrent_state
        v_new = v_i - v_prime
        attn_inter = (q_i * g[:, :, i, :, None].exp()) @ last_recurrent_state
        core_attn_out[:, :, i] = attn_inter + attn @ v_new
        last_recurrent_state = (
            last_recurrent_state * g[:, :, i, -1, None, None].exp()
            + (k_i * (g[:, :, i, -1, None] - g[:, :, i]).exp()[..., None]).transpose(-1, -2) @ v_new
        )

    if not output_final_state:
        last_recurrent_state = None
    core_attn_out = core_attn_out.reshape(core_attn_out.shape[0], core_attn_out.shape[1], -1, core_attn_out.shape[-1])
    core_attn_out = core_attn_out[:, :, :sequence_length]
    core_attn_out = core_attn_out.transpose(1, 2).contiguous().to(initial_dtype)
    return core_attn_out, last_recurrent_state


def torch_recurrent_gated_delta_rule(
    query, key, value, g, beta, initial_state, output_final_state, use_qk_l2norm_in_kernel=False
):
    initial_dtype = query.dtype
    if use_qk_l2norm_in_kernel:
        query = l2norm(query, dim=-1, eps=1e-6)
        key = l2norm(key, dim=-1, eps=1e-6)
    query, key, value, beta, g = [
        x.transpose(1, 2).contiguous().to(torch.float32) for x in (query, key, value, beta, g)
    ]

    batch_size, num_heads, sequence_length, k_head_dim = key.shape
    v_head_dim = value.shape[-1]
    scale = 1 / (query.shape[-1] ** 0.5)
    query = query * scale

    core_attn_out = torch.zeros(batch_size, num_heads, sequence_length, v_head_dim).to(value)
    last_recurrent_state = (
        torch.zeros(batch_size, num_heads, k_head_dim, v_head_dim).to(value)
        if initial_state is None
        else initial_state.to(value)
    )

    for i in range(sequence_length):
        q_t = query[:, :, i]
        k_t = key[:, :, i]
        v_t = value[:, :, i]
        g_t = g[:, :, i].exp().unsqueeze(-1).unsqueeze(-1)
        beta_t = beta[:, :, i].unsqueeze(-1)

        last_recurrent_state = last_recurrent_state * g_t
        kv_mem = (last_recurrent_state * k_t.unsqueeze(-1)).sum(dim=-2)
        delta = (v_t - kv_mem) * beta_t
        last_recurrent_state = last_recurrent_state + k_t.unsqueeze(-1) * delta.unsqueeze(-2)
        core_attn_out[:, :, i] = (last_recurrent_state * q_t.unsqueeze(-1)).sum(dim=-2)

    if not output_final_state:
        last_recurrent_state = None
    core_attn_out = core_attn_out.transpose(1, 2).contiguous().to(initial_dtype)
    return core_attn_out, last_recurrent_state


class Qwen3_5GatedDeltaNet(nn.Module):
    def __init__(self, config: Qwen3_5Config, layer_idx: int):
        super().__init__()
        self.hidden_size = config.hidden_size
        self.num_v_heads = config.linear_num_value_heads
        self.num_k_heads = config.linear_num_key_heads
        self.head_k_dim = config.linear_key_head_dim
        self.head_v_dim = config.linear_value_head_dim
        self.key_dim = self.head_k_dim * self.num_k_heads
        self.value_dim = self.head_v_dim * self.num_v_heads

        self.conv_kernel_size = config.linear_conv_kernel_dim
        self.layer_idx = layer_idx
        self.activation = config.hidden_act
        self.act = ACT2FN[config.hidden_act]
        self.layer_norm_epsilon = config.rms_norm_eps

        # QKV
        self.conv_dim = self.key_dim * 2 + self.value_dim
        self.conv1d = nn.Conv1d(
            in_channels=self.conv_dim,
            out_channels=self.conv_dim,
            bias=False,
            kernel_size=self.conv_kernel_size,
            groups=self.conv_dim,
            padding=self.conv_kernel_size - 1,
        )

        # time step projection (discretization)
        # instantiate once and copy inv_dt in init_weights of PretrainedModel
        self.dt_bias = nn.Parameter(torch.ones(self.num_v_heads))

        A = torch.empty(self.num_v_heads).uniform_(0, 16)
        self.A_log = nn.Parameter(torch.log(A))

        self.norm = (
            Qwen3_5RMSNormGated(self.head_v_dim, eps=self.layer_norm_epsilon)
            if FusedRMSNormGated is None
            else FusedRMSNormGated(
                self.head_v_dim,
                eps=self.layer_norm_epsilon,
                activation=self.activation,
                device=torch.cuda.current_device(),
                dtype=config.dtype if config.dtype is not None else torch.get_default_dtype(),
            )
        )

        self.out_proj = nn.Linear(self.value_dim, self.hidden_size, bias=False)

        self.causal_conv1d_fn = causal_conv1d_fn
        self.causal_conv1d_update = causal_conv1d_update or torch_causal_conv1d_update
        self.chunk_gated_delta_rule = chunk_gated_delta_rule or torch_chunk_gated_delta_rule
        self.recurrent_gated_delta_rule = fused_recurrent_gated_delta_rule or torch_recurrent_gated_delta_rule

        if not is_fast_path_available:
            logger.warning_once(
                "The fast path is not available because one of the required library is not installed. Falling back to "
                "torch implementation. To install follow https://github.com/fla-org/flash-linear-attention#installation and"
                " https://github.com/Dao-AILab/causal-conv1d"
            )

        self.in_proj_qkv = nn.Linear(self.hidden_size, self.key_dim * 2 + self.value_dim, bias=False)
        self.in_proj_z = nn.Linear(self.hidden_size, self.value_dim, bias=False)
        self.in_proj_b = nn.Linear(self.hidden_size, self.num_v_heads, bias=False)
        self.in_proj_a = nn.Linear(self.hidden_size, self.num_v_heads, bias=False)

    def forward(
        self,
        hidden_states: torch.Tensor,
        cache_params: Cache | None = None,
        attention_mask: torch.Tensor | None = None,
    ):
        hidden_states = apply_mask_to_padding_states(hidden_states, attention_mask)

        # Set up dimensions for reshapes later
        batch_size, seq_len, _ = hidden_states.shape

        use_precomputed_states = (
            cache_params is not None and cache_params.has_previous_state(self.layer_idx) and seq_len == 1
        )

        # getting projected states from cache if it exists
        if use_precomputed_states:
            conv_state = cache_params.layers[self.layer_idx].conv_states
            recurrent_state = cache_params.layers[self.layer_idx].recurrent_states

        mixed_qkv = self.in_proj_qkv(hidden_states)
        mixed_qkv = mixed_qkv.transpose(1, 2)

        z = self.in_proj_z(hidden_states)
        z = z.reshape(batch_size, seq_len, -1, self.head_v_dim)

        b = self.in_proj_b(hidden_states)
        a = self.in_proj_a(hidden_states)

        if use_precomputed_states:
            # 2. Convolution sequence transformation
            # NOTE: the conv state is updated in `causal_conv1d_update`
            mixed_qkv = self.causal_conv1d_update(
                mixed_qkv,
                conv_state,
                self.conv1d.weight.squeeze(1),
                self.conv1d.bias,
                self.activation,
            )
        else:
            if cache_params is not None:
                conv_state = F.pad(mixed_qkv, (self.conv_kernel_size - mixed_qkv.shape[-1], 0))
                conv_state = cache_params.update_conv_state(conv_state, self.layer_idx)
            if self.causal_conv1d_fn is not None:
                mixed_qkv = self.causal_conv1d_fn(
                    x=mixed_qkv,
                    weight=self.conv1d.weight.squeeze(1),
                    bias=self.conv1d.bias,
                    activation=self.activation,
                    seq_idx=None,
                )
            else:
                mixed_qkv = F.silu(self.conv1d(mixed_qkv)[:, :, :seq_len])

        mixed_qkv = mixed_qkv.transpose(1, 2)
        query, key, value = torch.split(
            mixed_qkv,
            [
                self.key_dim,
                self.key_dim,
                self.value_dim,
            ],
            dim=-1,
        )

        query = query.reshape(batch_size, seq_len, -1, self.head_k_dim)
        key = key.reshape(batch_size, seq_len, -1, self.head_k_dim)
        value = value.reshape(batch_size, seq_len, -1, self.head_v_dim)

        beta = b.sigmoid()
        # If the model is loaded in fp16, without the .float() here, A might be -inf
        g = -self.A_log.float().exp() * F.softplus(a.float() + self.dt_bias)
        if self.num_v_heads // self.num_k_heads > 1:
            query = query.repeat_interleave(self.num_v_heads // self.num_k_heads, dim=2)
            key = key.repeat_interleave(self.num_v_heads // self.num_k_heads, dim=2)

        if not use_precomputed_states:
            core_attn_out, last_recurrent_state = self.chunk_gated_delta_rule(
                query,
                key,
                value,
                g=g,
                beta=beta,
                initial_state=None,
                output_final_state=cache_params is not None,
                use_qk_l2norm_in_kernel=True,
            )

        else:
            core_attn_out, last_recurrent_state = self.recurrent_gated_delta_rule(
                query,
                key,
                value,
                g=g,
                beta=beta,
                initial_state=recurrent_state,
                output_final_state=cache_params is not None,
                use_qk_l2norm_in_kernel=True,
            )

        # Update cache
        if cache_params is not None:
            cache_params.update_recurrent_state(last_recurrent_state, self.layer_idx)

        # reshape input data into 2D tensor
        core_attn_out = core_attn_out.reshape(-1, self.head_v_dim)
        z = z.reshape(-1, self.head_v_dim)
        core_attn_out = self.norm(core_attn_out, z)
        core_attn_out = core_attn_out.reshape(batch_size, seq_len, -1)

        output = self.out_proj(core_attn_out)
        return output


def rotate_half(x):
    """Rotates half the hidden dims of the input."""
    x1 = x[..., : x.shape[-1] // 2]
    x2 = x[..., x.shape[-1] // 2 :]
    return torch.cat((-x2, x1), dim=-1)


# Adapted from transformers.models.glm.modular_glm.apply_rotary_pos_emb
def apply_rotary_pos_emb(q, k, cos, sin, unsqueeze_dim=1):
    """Applies Rotary Position Embedding to the query and key tensors.

    Removes the interleaving of cos and sin from GLM

    Args:
        q (`torch.Tensor`): The query tensor.
        k (`torch.Tensor`): The key tensor.
        cos (`torch.Tensor`): The cosine part of the rotary embedding.
        sin (`torch.Tensor`): The sine part of the rotary embedding.
        unsqueeze_dim (`int`, *optional*, defaults to 1):
            The 'unsqueeze_dim' argument specifies the dimension along which to unsqueeze cos[position_ids] and
            sin[position_ids] so that they can be properly broadcasted to the dimensions of q and k. For example, note
            that cos[position_ids] and sin[position_ids] have the shape [batch_size, seq_len, head_dim]. Then, if q and
            k have the shape [batch_size, heads, seq_len, head_dim], then setting unsqueeze_dim=1 makes
            cos[position_ids] and sin[position_ids] broadcastable to the shapes of q and k. Similarly, if q and k have
            the shape [batch_size, seq_len, heads, head_dim], then set unsqueeze_dim=2.
    Returns:
        `tuple(torch.Tensor)` comprising of the query and key tensors rotated using the Rotary Position Embedding.
    """
    cos = cos.unsqueeze(unsqueeze_dim)
    sin = sin.unsqueeze(unsqueeze_dim)

    # Keep half or full tensor for later concatenation
    rotary_dim = cos.shape[-1]
    q_rot, q_pass = q[..., :rotary_dim], q[..., rotary_dim:]
    k_rot, k_pass = k[..., :rotary_dim], k[..., rotary_dim:]

    # Apply rotary embeddings on the first half or full tensor
    q_embed = (q_rot * cos) + (rotate_half(q_rot) * sin)
    k_embed = (k_rot * cos) + (rotate_half(k_rot) * sin)

    # Concatenate back to full shape
    q_embed = torch.cat([q_embed, q_pass], dim=-1)
    k_embed = torch.cat([k_embed, k_pass], dim=-1)
    return q_embed, k_embed


def repeat_kv(hidden_states: torch.Tensor, n_rep: int) -> torch.Tensor:
    """
    This is the equivalent of torch.repeat_interleave(x, dim=1, repeats=n_rep). The hidden states go from (batch,
    num_key_value_heads, seqlen, head_dim) to (batch, num_attention_heads, seqlen, head_dim)
    """
    batch, num_key_value_heads, slen, head_dim = hidden_states.shape
    if n_rep == 1:
        return hidden_states
    hidden_states = hidden_states[:, :, None, :, :].expand(batch, num_key_value_heads, n_rep, slen, head_dim)
    return hidden_states.reshape(batch, num_key_value_heads * n_rep, slen, head_dim)


def eager_attention_forward(
    module: nn.Module,
    query: torch.Tensor,
    key: torch.Tensor,
    value: torch.Tensor,
    attention_mask: torch.Tensor | None,
    scaling: float,
    dropout: float = 0.0,
    **kwargs: Unpack[TransformersKwargs],
):
    key_states = repeat_kv(key, module.num_key_value_groups)
    value_states = repeat_kv(value, module.num_key_value_groups)

    attn_weights = torch.matmul(query, key_states.transpose(2, 3)) * scaling
    if attention_mask is not None:
        attn_weights = attn_weights + attention_mask

    attn_weights = nn.functional.softmax(attn_weights, dim=-1, dtype=torch.float32).to(query.dtype)
    attn_weights = nn.functional.dropout(attn_weights, p=dropout, training=module.training)
    attn_output = torch.matmul(attn_weights, value_states)
    attn_output = attn_output.transpose(1, 2).contiguous()

    return attn_output, attn_weights


@use_kernelized_func(apply_rotary_pos_emb)
class Qwen3_5Attention(nn.Module):
    """Multi-headed attention from 'Attention Is All You Need' paper"""

    def __init__(self, config: Qwen3_5Config, layer_idx: int):
        super().__init__()
        self.config = config
        self.layer_idx = layer_idx
        self.head_dim = getattr(config, "head_dim", config.hidden_size // config.num_attention_heads)
        self.num_key_value_groups = config.num_attention_heads // config.num_key_value_heads
        self.scaling = self.head_dim**-0.5
        self.attention_dropout = config.attention_dropout
        self.is_causal = True
        self.q_proj = nn.Linear(
            config.hidden_size, config.num_attention_heads * self.head_dim * 2, bias=config.attention_bias
        )
        self.k_proj = nn.Linear(
            config.hidden_size, config.num_key_value_heads * self.head_dim, bias=config.attention_bias
        )
        self.v_proj = nn.Linear(
            config.hidden_size, config.num_key_value_heads * self.head_dim, bias=config.attention_bias
        )
        self.o_proj = nn.Linear(
            config.num_attention_heads * self.head_dim, config.hidden_size, bias=config.attention_bias
        )
        self.q_norm = Qwen3_5RMSNorm(self.head_dim, eps=config.rms_norm_eps)  # unlike olmo, only on the head dim!
        self.k_norm = Qwen3_5RMSNorm(self.head_dim, eps=config.rms_norm_eps)  # thus post q_norm does not need reshape

    def forward(
        self,
        hidden_states: torch.Tensor,
        position_embeddings: tuple[torch.Tensor, torch.Tensor],
        attention_mask: torch.Tensor | None,
        past_key_values: Cache | None = None,
        **kwargs: Unpack[FlashAttentionKwargs],
    ) -> tuple[torch.Tensor, torch.Tensor | None]:
        input_shape = hidden_states.shape[:-1]
        hidden_shape = (*input_shape, -1, self.head_dim)

        query_states, gate = torch.chunk(
            self.q_proj(hidden_states).view(*input_shape, -1, self.head_dim * 2), 2, dim=-1
        )
        gate = gate.reshape(*input_shape, -1)

        query_states = self.q_norm(query_states.view(hidden_shape)).transpose(1, 2)
        key_states = self.k_norm(self.k_proj(hidden_states).view(hidden_shape)).transpose(1, 2)
        value_states = self.v_proj(hidden_states).view(hidden_shape).transpose(1, 2)

        cos, sin = position_embeddings
        query_states, key_states = apply_rotary_pos_emb(query_states, key_states, cos, sin)

        if past_key_values is not None:
            key_states, value_states = past_key_values.update(key_states, value_states, self.layer_idx)

        attention_interface: Callable = ALL_ATTENTION_FUNCTIONS.get_interface(
            self.config._attn_implementation, eager_attention_forward
        )

        attn_output, attn_weights = attention_interface(
            self,
            query_states,
            key_states,
            value_states,
            attention_mask,
            dropout=0.0 if not self.training else self.attention_dropout,
            scaling=self.scaling,
            **kwargs,
        )

        attn_output = attn_output.reshape(*input_shape, -1).contiguous()
        attn_output = attn_output * torch.sigmoid(gate)

        attn_output = self.o_proj(attn_output)
        return attn_output, attn_weights


class Qwen3_5MLP(nn.Module):
    def __init__(self, config: Qwen3_5Config, intermediate_size: int):
        super().__init__()
        self.config = config
        self.hidden_size = config.hidden_size
        self.intermediate_size = intermediate_size
        self.gate_proj = nn.Linear(self.hidden_size, self.intermediate_size, bias=False)
        self.up_proj = nn.Linear(self.hidden_size, self.intermediate_size, bias=False)
        self.down_proj = nn.Linear(self.intermediate_size, self.hidden_size, bias=False)
        self.act_fn = ACT2FN[config.hidden_act]

    def forward(self, x):
        down_proj = self.down_proj(self.act_fn(self.gate_proj(x)) * self.up_proj(x))
        return down_proj


class Qwen3_5RMSNorm(nn.Module):
    def __init__(self, dim: int, eps: float = 1e-6):
        super().__init__()
        self.eps = eps
        self.weight = nn.Parameter(torch.zeros(dim))

    def _norm(self, x):
        return x * torch.rsqrt(x.pow(2).mean(-1, keepdim=True) + self.eps)

    def forward(self, x):
        output = self._norm(x.float())
        # Llama does x.to(float16) * w whilst Qwen3_5 is (x * w).to(float16)
        # See https://github.com/huggingface/transformers/pull/29402
        output = output * (1.0 + self.weight.float())
        return output.type_as(x)

    def extra_repr(self):
        return f"{tuple(self.weight.shape)}, eps={self.eps}"


class Qwen3_5DecoderLayer(GradientCheckpointingLayer):
    def __init__(self, config: Qwen3_5TextConfig, layer_idx: int):
        super().__init__()
        self.hidden_size = config.hidden_size
        self.layer_type = config.layer_types[layer_idx]
        if self.layer_type == "linear_attention":
            self.linear_attn = Qwen3_5GatedDeltaNet(config, layer_idx)
        elif self.layer_type == "full_attention":
            self.self_attn = Qwen3_5Attention(config, layer_idx)
        self.mlp = Qwen3_5MLP(config, config.intermediate_size)
        self.input_layernorm = Qwen3_5RMSNorm(config.hidden_size, eps=config.rms_norm_eps)
        self.post_attention_layernorm = Qwen3_5RMSNorm(config.hidden_size, eps=config.rms_norm_eps)

    def forward(
        self,
        hidden_states: torch.Tensor,
        position_embeddings: tuple[torch.Tensor, torch.Tensor],
        attention_mask: torch.Tensor | None = None,
        position_ids: torch.LongTensor | None = None,
        past_key_values: Cache | None = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> torch.FloatTensor:
        residual = hidden_states

        hidden_states = self.input_layernorm(hidden_states)

        # Token Mixer
        if self.layer_type == "linear_attention":
            hidden_states = self.linear_attn(
                hidden_states=hidden_states,
                cache_params=past_key_values,
                attention_mask=attention_mask,
            )
        elif self.layer_type == "full_attention":
            # Self Attention
            hidden_states, _ = self.self_attn(
                hidden_states=hidden_states,
                attention_mask=attention_mask,
                position_ids=position_ids,
                past_key_values=past_key_values,
                position_embeddings=position_embeddings,
                **kwargs,
            )

        hidden_states = residual + hidden_states

        # Fully Connected
        residual = hidden_states
        hidden_states = self.post_attention_layernorm(hidden_states)
        hidden_states = self.mlp(hidden_states)
        hidden_states = residual + hidden_states

        return hidden_states


class Qwen3_5PreTrainedModel(PreTrainedModel):
    config: Qwen3_5Config
    base_model_prefix = "model"
    supports_gradient_checkpointing = True
    _no_split_modules = ["Qwen3_5DecoderLayer", "Qwen3_5VisionBlock"]
    _skip_keys_device_placement = "past_key_values"
    _supports_flash_attn = True
    _supports_sdpa = True
    _keys_to_ignore_on_load_unexpected = [r"^mtp.*"]
    _can_record_outputs = {
        "hidden_states": Qwen3_5DecoderLayer,
        "attentions": Qwen3_5Attention,
    }
    _is_stateful = True

    @torch.no_grad()
    def _init_weights(self, module):
        super()._init_weights(module)
        if isinstance(module, Qwen3_5GatedDeltaNet):
            init.ones_(module.dt_bias)
            init.copy_(module.A_log, torch.empty_like(module.A_log).uniform_(0, 16).log_())
        # We initialize with 0s to be 1 centered as the RMSNorm here does (1 + weight)
        elif isinstance(module, Qwen3_5RMSNorm):
            init.zeros_(module.weight)
        elif isinstance(module, Qwen3_5VisionRotaryEmbedding):
            inv_freq = 1.0 / (module.theta ** (torch.arange(0, module.dim, 2, dtype=torch.float) / module.dim))
            init.copy_(module.inv_freq, inv_freq)


class Qwen3_5VisionMLP(nn.Module):
    def __init__(self, config):
        super().__init__()
        self.hidden_size = config.hidden_size
        self.intermediate_size = config.intermediate_size
        self.linear_fc1 = nn.Linear(self.hidden_size, self.intermediate_size, bias=True)
        self.linear_fc2 = nn.Linear(self.intermediate_size, self.hidden_size, bias=True)
        self.act_fn = ACT2FN[config.hidden_act]

    def forward(self, hidden_state):
        return self.linear_fc2(self.act_fn(self.linear_fc1(hidden_state)))


class Qwen3_5VisionPatchEmbed(nn.Module):
    def __init__(self, config) -> None:
        super().__init__()
        self.patch_size = config.patch_size
        self.temporal_patch_size = config.temporal_patch_size
        self.in_channels = config.in_channels
        self.embed_dim = config.hidden_size

        kernel_size = [self.temporal_patch_size, self.patch_size, self.patch_size]
        self.proj = nn.Conv3d(self.in_channels, self.embed_dim, kernel_size=kernel_size, stride=kernel_size, bias=True)

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        target_dtype = self.proj.weight.dtype
        hidden_states = hidden_states.view(
            -1, self.in_channels, self.temporal_patch_size, self.patch_size, self.patch_size
        )
        hidden_states = self.proj(hidden_states.to(dtype=target_dtype)).view(-1, self.embed_dim)
        return hidden_states


class Qwen3_5VisionPatchMerger(nn.Module):
    def __init__(self, config: Qwen3_5VisionConfig, use_postshuffle_norm=False) -> None:
        super().__init__()
        self.hidden_size = config.hidden_size * (config.spatial_merge_size**2)
        self.use_postshuffle_norm = use_postshuffle_norm
        self.norm = nn.LayerNorm(self.hidden_size if use_postshuffle_norm else config.hidden_size, eps=1e-6)
        self.linear_fc1 = nn.Linear(self.hidden_size, self.hidden_size)
        self.act_fn = nn.GELU()
        self.linear_fc2 = nn.Linear(self.hidden_size, config.out_hidden_size)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = self.norm(x.view(-1, self.hidden_size) if self.use_postshuffle_norm else x).view(-1, self.hidden_size)
        x = self.linear_fc2(self.act_fn(self.linear_fc1(x)))
        return x


def apply_rotary_pos_emb_vision(
    q: torch.Tensor, k: torch.Tensor, cos: torch.Tensor, sin: torch.Tensor
) -> tuple[torch.Tensor, torch.Tensor]:
    orig_q_dtype = q.dtype
    orig_k_dtype = k.dtype
    q, k = q.float(), k.float()
    cos, sin = cos.unsqueeze(-2).float(), sin.unsqueeze(-2).float()
    q_embed = (q * cos) + (rotate_half(q) * sin)
    k_embed = (k * cos) + (rotate_half(k) * sin)
    q_embed = q_embed.to(orig_q_dtype)
    k_embed = k_embed.to(orig_k_dtype)
    return q_embed, k_embed


class Qwen3_5VisionAttention(nn.Module):
    def __init__(self, config: Qwen3_5VisionConfig) -> None:
        super().__init__()
        self.dim = config.hidden_size
        self.num_heads = config.num_heads
        self.head_dim = self.dim // self.num_heads
        self.num_key_value_groups = 1  # needed for eager attention
        self.qkv = nn.Linear(self.dim, self.dim * 3, bias=True)
        self.proj = nn.Linear(self.dim, self.dim)
        self.scaling = self.head_dim**-0.5
        self.config = config
        self.attention_dropout = 0.0
        self.is_causal = False

    def forward(
        self,
        hidden_states: torch.Tensor,
        cu_seqlens: torch.Tensor,
        rotary_pos_emb: torch.Tensor | None = None,
        position_embeddings: tuple[torch.Tensor, torch.Tensor] | None = None,
        **kwargs,
    ) -> torch.Tensor:
        seq_length = hidden_states.shape[0]
        query_states, key_states, value_states = (
            self.qkv(hidden_states).reshape(seq_length, 3, self.num_heads, -1).permute(1, 0, 2, 3).unbind(0)
        )
        cos, sin = position_embeddings
        query_states, key_states = apply_rotary_pos_emb_vision(query_states, key_states, cos, sin)

        query_states = query_states.transpose(0, 1).unsqueeze(0)
        key_states = key_states.transpose(0, 1).unsqueeze(0)
        value_states = value_states.transpose(0, 1).unsqueeze(0)

        attention_interface: Callable = ALL_ATTENTION_FUNCTIONS.get_interface(
            self.config._attn_implementation, eager_attention_forward
        )

        if is_flash_attention_requested(self.config):
            # Flash Attention: Use cu_seqlens for variable length attention
            max_seqlen = (cu_seqlens[1:] - cu_seqlens[:-1]).max()
            attn_output, _ = attention_interface(
                self,
                query_states,
                key_states,
                value_states,
                attention_mask=None,
                scaling=self.scaling,
                dropout=0.0 if not self.training else self.attention_dropout,
                cu_seq_lens_q=cu_seqlens,
                cu_seq_lens_k=cu_seqlens,
                max_length_q=max_seqlen,
                max_length_k=max_seqlen,
                is_causal=False,
                **kwargs,
            )
        else:
            # Other implementations: Process each chunk separately
            lengths = cu_seqlens[1:] - cu_seqlens[:-1]
            splits = [
                torch.split(tensor, lengths.tolist(), dim=2) for tensor in (query_states, key_states, value_states)
            ]

            attn_outputs = [
                attention_interface(
                    self,
                    q,
                    k,
                    v,
                    attention_mask=None,
                    scaling=self.scaling,
                    dropout=0.0 if not self.training else self.attention_dropout,
                    is_causal=False,
                    **kwargs,
                )[0]
                for q, k, v in zip(*splits)
            ]
            attn_output = torch.cat(attn_outputs, dim=1)

        attn_output = attn_output.reshape(seq_length, -1).contiguous()
        attn_output = self.proj(attn_output)
        return attn_output


class Qwen3_5VisionBlock(GradientCheckpointingLayer):
    def __init__(self, config, attn_implementation: str = "sdpa") -> None:
        super().__init__()
        self.norm1 = nn.LayerNorm(config.hidden_size, eps=1e-6)
        self.norm2 = nn.LayerNorm(config.hidden_size, eps=1e-6)
        self.attn = Qwen3_5VisionAttention(config=config)
        self.mlp = Qwen3_5VisionMLP(config=config)

    @auto_docstring
    def forward(
        self,
        hidden_states: torch.Tensor,
        cu_seqlens: torch.Tensor,
        rotary_pos_emb: torch.Tensor | None = None,
        position_embeddings: tuple[torch.Tensor, torch.Tensor] | None = None,
        **kwargs,
    ) -> torch.Tensor:
        r"""
        cu_seqlens (`torch.Tensor`):
            Cumulative sequence lengths used for packed variable-length attention in Flash Attention kernels.
        rotary_pos_emb (`torch.Tensor`, *optional*):
            Precomputed rotary positional embeddings applied to the vision attention query/key states.
        """
        hidden_states = hidden_states + self.attn(
            self.norm1(hidden_states),
            cu_seqlens=cu_seqlens,
            rotary_pos_emb=rotary_pos_emb,
            position_embeddings=position_embeddings,
            **kwargs,
        )
        hidden_states = hidden_states + self.mlp(self.norm2(hidden_states))
        return hidden_states


class Qwen3_5VisionModel(Qwen3_5PreTrainedModel):
    config: Qwen3_5VisionConfig
    input_modalities = ("image", "video")
    _no_split_modules = ["Qwen3_5VisionBlock"]
    _can_record_outputs = {
        "hidden_states": Qwen3_5VisionBlock,
        "attentions": Qwen3_5VisionAttention,
    }

    def __init__(self, config, *inputs, **kwargs) -> None:
        super().__init__(config, *inputs, **kwargs)
        self.spatial_merge_size = config.spatial_merge_size
        self.patch_size = config.patch_size
        self.spatial_merge_unit = self.spatial_merge_size * self.spatial_merge_size

        self.patch_embed = Qwen3_5VisionPatchEmbed(
            config=config,
        )

        self.pos_embed = nn.Embedding(config.num_position_embeddings, config.hidden_size)
        self.num_grid_per_side = int(config.num_position_embeddings**0.5)

        head_dim = config.hidden_size // config.num_heads
        self.rotary_pos_emb = Qwen3_5VisionRotaryEmbedding(head_dim // 2)

        self.blocks = nn.ModuleList([Qwen3_5VisionBlock(config) for _ in range(config.depth)])
        self.merger = Qwen3_5VisionPatchMerger(
            config=config,
            use_postshuffle_norm=False,
        )

        self.gradient_checkpointing = False

        self.post_init()

    def rot_pos_emb(self, grid_thw: torch.Tensor) -> torch.Tensor:
        merge_size = self.spatial_merge_size
        grid_thw_list = grid_thw.tolist()

        max_hw = max(max(h, w) for _, h, w in grid_thw_list)
        freq_table = self.rotary_pos_emb(max_hw)  # (max_hw, dim // 2)
        device = freq_table.device

        total_tokens = sum(t * h * w for t, h, w in grid_thw_list)
        pos_ids = torch.empty((total_tokens, 2), dtype=torch.long, device=device)

        offset = 0
        for num_frames, height, width in grid_thw_list:
            merged_h, merged_w = height // merge_size, width // merge_size

            block_rows = torch.arange(merged_h, device=device)  # block row indices
            block_cols = torch.arange(merged_w, device=device)  # block col indices
            intra_row = torch.arange(merge_size, device=device)  # intra-block row offsets
            intra_col = torch.arange(merge_size, device=device)  # intra-block col offsets

            # Compute full-resolution positions
            row_idx = block_rows[:, None, None, None] * merge_size + intra_row[None, None, :, None]
            col_idx = block_cols[None, :, None, None] * merge_size + intra_col[None, None, None, :]

            row_idx = row_idx.expand(merged_h, merged_w, merge_size, merge_size).reshape(-1)
            col_idx = col_idx.expand(merged_h, merged_w, merge_size, merge_size).reshape(-1)

            coords = torch.stack((row_idx, col_idx), dim=-1)

            if num_frames > 1:
                coords = coords.repeat(num_frames, 1)

            num_tokens = coords.shape[0]
            pos_ids[offset : offset + num_tokens] = coords
            offset += num_tokens

        embeddings = freq_table[pos_ids]  # lookup rotary embeddings
        embeddings = embeddings.flatten(1)
        return embeddings

    def fast_pos_embed_interpolate(self, grid_thw):
        grid_thw_list = grid_thw.tolist()
        grid_ts = [row[0] for row in grid_thw_list]
        grid_hs = [row[1] for row in grid_thw_list]
        grid_ws = [row[2] for row in grid_thw_list]
        device = self.pos_embed.weight.device

        idx_list = [[] for _ in range(4)]
        weight_list = [[] for _ in range(4)]

        for t, h, w in grid_thw_list:
            h_idxs = torch.linspace(0, self.num_grid_per_side - 1, h)
            w_idxs = torch.linspace(0, self.num_grid_per_side - 1, w)

            h_idxs_floor = h_idxs.int()
            w_idxs_floor = w_idxs.int()
            h_idxs_ceil = (h_idxs.int() + 1).clip(max=self.num_grid_per_side - 1)
            w_idxs_ceil = (w_idxs.int() + 1).clip(max=self.num_grid_per_side - 1)

            dh = h_idxs - h_idxs_floor
            dw = w_idxs - w_idxs_floor

            base_h = h_idxs_floor * self.num_grid_per_side
            base_h_ceil = h_idxs_ceil * self.num_grid_per_side

            indices = [
                (base_h[None].T + w_idxs_floor[None]).flatten(),
                (base_h[None].T + w_idxs_ceil[None]).flatten(),
                (base_h_ceil[None].T + w_idxs_floor[None]).flatten(),
                (base_h_ceil[None].T + w_idxs_ceil[None]).flatten(),
            ]

            weights = [
                ((1 - dh)[None].T * (1 - dw)[None]).flatten(),
                ((1 - dh)[None].T * dw[None]).flatten(),
                (dh[None].T * (1 - dw)[None]).flatten(),
                (dh[None].T * dw[None]).flatten(),
            ]

            for i in range(4):
                idx_list[i].extend(indices[i].tolist())
                weight_list[i].extend(weights[i].tolist())

        idx_tensor = torch.tensor(idx_list, dtype=torch.long, device=device)
        weight_tensor = torch.tensor(weight_list, dtype=self.pos_embed.weight.dtype, device=device)
        pos_embeds = self.pos_embed(idx_tensor).to(device) * weight_tensor[:, :, None]
        patch_pos_embeds = pos_embeds[0] + pos_embeds[1] + pos_embeds[2] + pos_embeds[3]

        patch_pos_embeds = patch_pos_embeds.split([h * w for h, w in zip(grid_hs, grid_ws)])

        patch_pos_embeds_permute = []
        merge_size = self.config.spatial_merge_size
        for pos_embed, t, h, w in zip(patch_pos_embeds, grid_ts, grid_hs, grid_ws):
            pos_embed = pos_embed.repeat(t, 1)
            pos_embed = (
                pos_embed.view(t, h // merge_size, merge_size, w // merge_size, merge_size, -1)
                .permute(0, 1, 3, 2, 4, 5)
                .flatten(0, 4)
            )
            patch_pos_embeds_permute.append(pos_embed)
        patch_pos_embeds = torch.cat(patch_pos_embeds_permute)
        return patch_pos_embeds

    @merge_with_config_defaults
    @capture_outputs
    def forward(
        self,
        hidden_states: torch.Tensor,
        grid_thw: torch.Tensor,
        keep_token_mask: Optional[torch.Tensor] = None,
        **kwargs,
    ) -> torch.Tensor:
        """
        Args:
            hidden_states (`torch.Tensor` of shape `(seq_len, hidden_size)`):
                The final hidden states of the model.
            grid_thw (`torch.Tensor` of shape `(num_images_or_videos, 3)`):
                The temporal, height and width of feature shape of each image in LLM.
            keep_token_mask (`torch.Tensor` of shape ``(sum_i t_i * (h_i // merge) * (w_i // merge),)``,
                *optional*):
                Boolean mask at **LLM-token granularity** (one entry per
                post-merger output token, equivalently one entry per
                ``spatial_merge_size × spatial_merge_size`` patch block).
                When provided, the corresponding patch blocks are dropped
                **after** ``patch_embed`` and pos-embed addition, BEFORE
                the ViT blocks run. ``cu_seqlens`` and ``rotary_pos_emb``
                are filtered to match. The merger still receives a
                sequence whose length is a multiple of merge² because we
                drop at token granularity, so its ``.view(-1, merge²*D)``
                reshape stays valid. Used by the SD-RPN window-encoding
                inference path (``experiments/exploration/foreground_window_encoding/``)
                to skip ViT compute on background regions of the bbox crop.

        Returns:
            `torch.Tensor`: hidden_states.
        """

        hidden_states = self.patch_embed(hidden_states)

        pos_embeds = self.fast_pos_embed_interpolate(grid_thw)
        hidden_states = hidden_states + pos_embeds

        rotary_pos_emb = self.rot_pos_emb(grid_thw)

        seq_len, _ = hidden_states.size()
        hidden_states = hidden_states.reshape(seq_len, -1)
        rotary_pos_emb = rotary_pos_emb.reshape(seq_len, -1)

        if keep_token_mask is not None:
            merge_sq = self.spatial_merge_size * self.spatial_merge_size
            # Patches are ordered as consecutive 2×2 (= merge_size²) blocks
            # per ``fast_pos_embed_interpolate`` / ``rot_pos_emb`` layout,
            # so replicating each token-level bool ``merge_sq`` times
            # yields the right patch-level mask.
            keep_patch_mask = (
                keep_token_mask.to(device=hidden_states.device, dtype=torch.bool)
                .repeat_interleave(merge_sq)
            )
            if keep_patch_mask.numel() != seq_len:
                raise ValueError(
                    f"keep_token_mask expanded to {keep_patch_mask.numel()} patches, "
                    f"expected {seq_len} from grid_thw."
                )
            hidden_states = hidden_states[keep_patch_mask]
            rotary_pos_emb = rotary_pos_emb[keep_patch_mask]
            # Rebuild cu_seqlens: each cu_seqlens segment was one frame
            # (h*w patches). Per-frame kept-token count × merge_sq gives
            # per-segment kept-patch count.
            per_seg_token_count = torch.repeat_interleave(
                (grid_thw[:, 1] // self.spatial_merge_size)
                * (grid_thw[:, 2] // self.spatial_merge_size),
                grid_thw[:, 0],
            )
            seg_offsets = F.pad(
                per_seg_token_count.cumsum(0)[:-1], (1, 0), value=0
            )
            kept_per_seg = torch.empty_like(per_seg_token_count)
            ktm = keep_token_mask.to(per_seg_token_count.device, dtype=per_seg_token_count.dtype)
            for s in range(per_seg_token_count.numel()):
                kept_per_seg[s] = ktm[seg_offsets[s]: seg_offsets[s] + per_seg_token_count[s]].sum()
            cu_seqlens = (kept_per_seg * merge_sq).cumsum(0).to(
                grid_thw.dtype if torch.jit.is_tracing() else torch.int32
            )
        else:
            cu_seqlens = torch.repeat_interleave(
                grid_thw[:, 1] * grid_thw[:, 2], grid_thw[:, 0]
            ).cumsum(
                dim=0,
                # Select dtype based on the following factors:
                #  - FA2 requires that cu_seqlens_q must have dtype int32
                #  - torch.onnx.export requires that cu_seqlens_q must have same dtype as grid_thw
                # See https://github.com/huggingface/transformers/pull/34852 for more information
                dtype=grid_thw.dtype if torch.jit.is_tracing() else torch.int32,
            )
        cu_seqlens = F.pad(cu_seqlens, (1, 0), value=0)

        emb = torch.cat((rotary_pos_emb, rotary_pos_emb), dim=-1)
        position_embeddings = (emb.cos(), emb.sin())

        for blk in self.blocks:
            hidden_states = blk(
                hidden_states,
                cu_seqlens=cu_seqlens,
                position_embeddings=position_embeddings,
                **kwargs,
            )

        merged_hidden_states = self.merger(hidden_states)

        return BaseModelOutputWithPooling(
            last_hidden_state=hidden_states,
            pooler_output=merged_hidden_states,
        )


@dataclass
@auto_docstring(
    custom_intro="""
    Base class for Llava outputs, with hidden states and attentions.
    """
)
class Qwen3_5ModelOutputWithPast(ModelOutput):
    r"""
    past_key_values (`Cache`, *optional*, returned when `use_cache=True` is passed or when `config.use_cache=True`):
        It is a [`~cache_utils.Cache`] instance. For more details, see our [kv cache guide](https://huggingface.co/docs/transformers/en/kv_cache).

        Contains pre-computed hidden-states (key and values in the self-attention blocks) that can be used (see
        `past_key_values` input) to speed up sequential decoding.
    rope_deltas (`torch.LongTensor` of shape `(batch_size, )`, *optional*):
        The rope index difference between sequence length and multimodal rope.
    """

    last_hidden_state: torch.FloatTensor | None = None
    past_key_values: Cache | None = None
    hidden_states: tuple[torch.FloatTensor] | None = None
    attentions: tuple[torch.FloatTensor] | None = None
    rope_deltas: torch.LongTensor | None = None
    twig_hidden_states: torch.FloatTensor | None = None
    pre_twig_ctx: dict | None = None


class Qwen3_5TextModel(Qwen3_5PreTrainedModel):
    config: Qwen3_5TextConfig

    def __init__(self, config: Qwen3_5TextConfig):
        super().__init__(config)
        self.embed_tokens = nn.Embedding(config.vocab_size, config.hidden_size, config.pad_token_id)
        self.layers = nn.ModuleList(
            [Qwen3_5DecoderLayer(config, layer_idx) for layer_idx in range(config.num_hidden_layers)]
        )
        self.norm = Qwen3_5RMSNorm(config.hidden_size, eps=config.rms_norm_eps)
        self.rotary_emb = Qwen3_5TextRotaryEmbedding(config=config)
        self.gradient_checkpointing = False

        # ---------------- SD-RPN twig layers ----------------
        # Set on the parent config (Qwen3_5Config) by the training entry
        # script: enable_twig, twig_K, twig_T, etc. A copy may also live
        # on the text_config; check both.
        self.enable_twig = bool(getattr(config, "enable_twig", False))
        self.twig_K = int(getattr(config, "twig_K", 0) or 0)
        self.twig_T = int(getattr(config, "twig_T", 0) or 0)

        # Qwen3.5 is a HYBRID model: only every Kth layer is
        # full_attention; the rest are linear_attention (gated_delta).
        # SD-RPN needs Q/K, which only exist on full_attention layers.
        # Convention: ``twig_K`` = index of the **first
        # twig layer** in the original model's layer numbering. Twig
        # replaces main path layers ``twig_K .. twig_K+twig_T-1``.
        # The last twig layer (feeds SD-RPN ROI head) corresponds to
        # original layer ``twig_K + twig_T - 1``; we want that layer to
        # be full_attention so the warm-start does a clean direct copy
        # for the loss-bearing layer.
        # Note: twig_layers themselves are always full_attention (forced
        # below), so the LAST twig's TYPE is guaranteed regardless of K.
        # This is just a sanity warning about the warm-start source.
        if self.enable_twig and self.twig_T > 0:
            last_src_idx = self.twig_K + self.twig_T - 1
            if 0 <= last_src_idx < len(config.layer_types):
                if config.layer_types[last_src_idx] != "full_attention":
                    print(
                        f"[Qwen3_5TextModel] WARNING: last twig source "
                        f"layer {last_src_idx} (twig_K={self.twig_K}, "
                        f"twig_T={self.twig_T}) is "
                        f"'{config.layer_types[last_src_idx]}'. "
                        f"twig_init will fall back to the nearest preceding "
                        f"full_attention layer. Available full-attn idxs: "
                        f"{[i for i, t in enumerate(config.layer_types) if t == 'full_attention']}"
                    )
        if self.enable_twig and self.twig_T > 0:
            # Force every twig layer to "full_attention" — linear-attention
            # layers don't expose a usable Q/K for the ROI head.
            twig_cfg = type(config)(**config.to_dict())
            twig_cfg.layer_types = [
                "full_attention" for _ in range(self.twig_T)
            ]
            # ``_attn_implementation_internal`` is set post-init on the
            # parent config (when the model is loaded with
            # ``attn_implementation="flash_attention_2"`` etc.). Rebuilding
            # twig_cfg via ``to_dict()`` doesn't carry this private attr —
            # without propagation, twig layers fall back to
            # ``eager_attention_forward`` whose mask handling diverges
            # from the parent's (e.g. flash_attention_2 passes None for
            # causal, which eager can't add to attn_weights). Mirror the
            # parent's attn_impl so twig layers use the same backend.
            for _attr in ("_attn_implementation_internal",
                          "_attn_implementation_autoset"):
                if hasattr(config, _attr):
                    setattr(twig_cfg, _attr, getattr(config, _attr))
            # layer_idx is local to twig_layers (0..twig_T-1) so it
            # indexes twig_cfg.layer_types correctly (length = twig_T).
            self.twig_layers = nn.ModuleList([
                Qwen3_5DecoderLayer(twig_cfg, layer_idx=i)
                for i in range(self.twig_T)
            ])
        else:
            self.twig_layers = None

        # ---------------- SD-RPN inference-time state ----------------
        # These attrs are written by lmms-eval simple/qwen3_5.py when
        # ``two_stage_roi=True``. They drive the 2-stage ROI augmentation
        # in ``forward`` below (same scheme as the Qwen2.5-VL batch fork).
        self.roi_enable2stage = bool(getattr(config, "roi_enable2stage", False))
        self.roi_conf_thresh = float(getattr(config, "roi_conf_thresh", 0.1))
        self.dynamic_conf_mode = "fixed"
        self.dynamic_conf_kwargs = None
        self.image_token_id = getattr(config, "image_token_id", None)
        self.video_token_id = getattr(config, "video_token_id", None)
        # Pixel size of one LLM visual token after vision-tower merge:
        # patch_size * spatial_merge_size. Default 16*2=32 for Qwen3.5-9B.
        self.img_llm_patch_size = int(
            getattr(config, "patch_size", 16)
        ) * int(getattr(config, "spatial_merge_size", 2))

        # Initialize weights and apply final processing
        self.post_init()

    @merge_with_config_defaults
    @capture_outputs
    @auto_docstring
    def forward(
        self,
        input_ids: torch.LongTensor | None = None,
        attention_mask: torch.Tensor | None = None,
        position_ids: torch.LongTensor | None = None,
        past_key_values: Cache | None = None,
        inputs_embeds: torch.FloatTensor | None = None,
        use_cache: bool | None = None,
        # ---- SD-RPN inference plumbing (passed by the Qwen3_5Model wrapper) ----
        image_grid_thw: torch.LongTensor | None = None,
        src_images: Optional[list] = None,
        image_processor: Optional[Any] = None,
        encode_image_fn: Optional[Callable] = None,
        image_token_start: int = 0,
        temp_input_ids: torch.LongTensor | None = None,
        pos_id_fn: Optional[Callable] = None,
        processor: Optional[Any] = None,
        labels: torch.LongTensor | None = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> BaseModelOutputWithPast:
        if (input_ids is None) ^ (inputs_embeds is not None):
            raise ValueError("You must specify exactly one of input_ids or inputs_embeds")

        if inputs_embeds is None:
            inputs_embeds = self.embed_tokens(input_ids)

        if use_cache and past_key_values is None:
            past_key_values = DynamicCache(config=self.config)

        # the hard coded `4` is for text, temporal, height and width.
        if position_ids is None:
            past_seen_tokens = past_key_values.get_seq_length() if past_key_values is not None else 0
            position_ids = torch.arange(inputs_embeds.shape[1], device=inputs_embeds.device) + past_seen_tokens
            position_ids = position_ids.view(1, 1, -1).expand(4, inputs_embeds.shape[0], -1)
        elif position_ids.ndim == 2:
            position_ids = position_ids[None, ...].expand(4, position_ids.shape[0], -1)

        if position_ids.ndim == 3 and position_ids.shape[0] == 4:
            text_position_ids = position_ids[0]
            position_ids = position_ids[1:]
        else:
            text_position_ids = None

        causal_mask = create_causal_mask(
            config=self.config,
            inputs_embeds=inputs_embeds,
            attention_mask=attention_mask,
            past_key_values=past_key_values,
            position_ids=text_position_ids,
        )
        linear_attn_mask = self._update_linear_attn_mask(attention_mask, past_key_values)

        # Save the original 2D padding mask + pre-layer embeddings; the
        # 2-stage SD-RPN augmentation (below) inserts sub-image features
        # into ``inputs_embeds_initial`` and replays all layers on the
        # extended sequence. ``inputs_embeds`` is not mutated by the
        # decoder layers (each layer returns a new tensor), so a plain
        # reference is sufficient — no clone needed.
        raw_attn_mask = attention_mask
        inputs_embeds_initial = inputs_embeds

        batch_size, seq_len = inputs_embeds.shape[:2]
        visual_token_counts = torch.zeros(
            batch_size, device=inputs_embeds.device, dtype=torch.long,
        )
        if image_grid_thw is not None and image_grid_thw.numel() > 0:
            if image_grid_thw.dim() == 1:
                image_grid_thw = image_grid_thw.unsqueeze(0)
            merge_size = int(getattr(self.config, "spatial_merge_size", 2))
            visual_token_counts = (
                image_grid_thw[:, 0] * image_grid_thw[:, 1] * image_grid_thw[:, 2]
            ) // (merge_size ** 2)

        visual_token_mask = None
        if (
            temp_input_ids is not None
            and self.image_token_id is not None
            and self.video_token_id is not None
        ):
            visual_token_mask = (
                (temp_input_ids == self.image_token_id)
                | (temp_input_ids == self.video_token_id)
            )

        # Gate the 2-stage augmentation. Inference-only, must have all
        # the cropping deps wired through, prefill (seq_len>1) only —
        # never on single-token decode steps.
        should_attempt_augment = (
            not self.training
            and self.enable_twig
            and self.twig_layers is not None
            and self.roi_enable2stage
            and src_images is not None
            and image_grid_thw is not None
            and image_processor is not None
            and encode_image_fn is not None
            and image_token_start > 0
            and seq_len > 1
            and visual_token_mask is not None
            and bool(visual_token_mask.any())
        )

        hidden_states = inputs_embeds
        position_embeddings = self.rotary_emb(hidden_states, position_ids)

        # Stage timing: inference prefill only. ``_qzt_on`` is False for
        # training and for decode steps, so the layer loop below is
        # untouched in every normal code path.
        _qzt_on = (
            qzt.enabled()
            and not self.training
            and seq_len > 1
            and not qzt.model_laps_suspended()
        )
        self._qzt_on = _qzt_on

        twig_hidden_states = None
        # Iter 27: pre_twig_ctx is bound here so it's a defined local
        # even when the twig branch doesn't fire this call (e.g. decode,
        # or labels all-truncated at very high MAX_PIXELS so the BCE
        # path skips). The trainer treats None as "ref-twig disabled
        # for this sample" and gracefully falls back.
        pre_twig_ctx = None
        augmented = False
        branch_point = self.twig_K - self.twig_T

        # SD-RPN training speedup: BCE loss is computed off
        # ``twig_hidden_states``; layers AFTER the last OPL-needed
        # source layer don't contribute to the loss or to a downstream
        # gradient path (everything outside ``twig_layers`` is frozen via
        # ``requires_grad=False`` in train_qwen.py:294-320). Break out
        # of the main loop early during training to skip those forward
        # FLOPs entirely. Opt-in via ``SKIP_POST_BRANCH=1``.
        # ``skip_after_layer`` = max(branch_point - 1, max(opl_layers))
        # so OPL hooks at e.g. layer 19 still fire even though
        # branch_point=18.
        _skip_post_branch = (
            self.training
            and self.enable_twig
            and self.twig_layers is not None
            and int(qz_getenv("SKIP_POST_BRANCH", "1")) == 1
        )
        _skip_after_layer = self.config.num_hidden_layers - 1
        if _skip_post_branch:
            try:
                from qwen_src.qwen3_5.online_pseudo_label import grounding_layer_set
                _family = getattr(self.config, "online_pseudo_label_family", None)
                _opl_layers = grounding_layer_set(_family) if _family else []
                _max_opl = max(_opl_layers) if _opl_layers else 0
                _skip_after_layer = max(branch_point - 1, _max_opl)
            except Exception:
                # If anything blows up looking up OPL layers, fall back
                # to running the full main path (correctness over speed).
                _skip_post_branch = False

        for i, decoder_layer in enumerate(self.layers[: self.config.num_hidden_layers]):
            layer_mask = linear_attn_mask if self.config.layer_types[i] == "linear_attention" else causal_mask

            hidden_states = decoder_layer(
                hidden_states,
                position_embeddings=position_embeddings,
                attention_mask=layer_mask,
                position_ids=text_position_ids,
                past_key_values=past_key_values,
                use_cache=use_cache,
                **kwargs,
            )

            # SD-RPN: branch off after layer twig_K - twig_T (the
            # "split point") and run the dedicated twig layers. The main
            # path keeps going through layers[twig_K-twig_T:] for the LM
            # logits; twig_layers diverge here for the ROI prediction.
            #
            # Only run TWIG at prefill (seq_len > 1). During decode
            # (seq_len == 1), the twig layers are passed
            # ``past_key_values=None, use_cache=False`` so they see only
            # the new token (k_len=1), but the ``causal_mask`` built at
            # the top of forward() was sized for the full
            # ``past_seen_tokens + seq_len`` length — which gives an
            # SDPA mask-shape mismatch ``[1, H, 1, 1]`` vs
            # ``[1, 1, 1, T_full]``. Decode also doesn't need a fresh
            # heatmap (the augmented sub-image features are already in
            # the cache), so skipping is both correct and a free
            # speedup (prefill-only TWIG gating).
            if (
                self.enable_twig
                and self.twig_layers is not None
                and (i + 1) == branch_point
                and seq_len > 1
            ):
                # Iter 27 (online_p_ref): save the pre-twig context so an
                # external ``RefTwigModule`` can run a Phase-A reference
                # twig on identical inputs, producing a resolution-matched
                # KL reference at training time. The saved tensors are
                # NOT cloned — they're aliases to the live tensors above;
                # consumers must run their ref twig BEFORE any in-place
                # mutation of these tensors elsewhere in the forward.
                # Stage boundary: everything up to here (ViT + embed +
                # main-path layers [0..branch)) is the shared source
                # prefill; the twig forward that follows is SD-RPN.
                if _qzt_on:
                    qzt.lap("t_src_prefill_ms")
                pre_twig_ctx = {
                    "hidden_states": hidden_states,
                    "position_embeddings": position_embeddings,
                    "attention_mask": causal_mask,
                    "position_ids": text_position_ids,
                    # Raw 2D (B,S) padding mask so an EAGER consumer (the
                    # online-p_ref ref twig, ref_twig.py) can build a 4D additive
                    # mask: ``causal_mask`` is flash's raw 2D mask under padding
                    # (bs>1 + variable image grids), and eager attention can't add
                    # a 2D mask to 4D attn_weights ("Sq vs B at dim 2" crash).
                    "raw_attn_mask": raw_attn_mask,
                }
                twig_hs = hidden_states
                for twig_layer in self.twig_layers:
                    twig_hs = twig_layer(
                        twig_hs,
                        position_embeddings=position_embeddings,
                        attention_mask=causal_mask,  # full attn always
                        position_ids=text_position_ids,
                        past_key_values=None,        # no cache reuse
                        use_cache=False,
                        **kwargs,
                    )
                twig_hidden_states = twig_hs

                # 2-stage inference: build ROI heatmaps from the last
                # twig layer; if any sample triggers, augment
                # ``inputs_embeds_initial`` with high-res sub-image
                # features and replay all layers on the extended seq.
                if should_attempt_augment:
                    aug_result = self._maybe_augment_with_roi(
                        rpn_hidden_states=twig_hs,
                        inputs_embeds_initial=inputs_embeds_initial,
                        raw_attn_mask=raw_attn_mask,
                        position_ids=position_ids,
                        text_position_ids=text_position_ids,
                        position_embeddings=position_embeddings,
                        image_grid_thw=image_grid_thw,
                        src_images=src_images,
                        image_processor=image_processor,
                        encode_image_fn=encode_image_fn,
                        image_token_start=image_token_start,
                        temp_input_ids=temp_input_ids,
                        pos_id_fn=pos_id_fn,
                        visual_token_mask=visual_token_mask,
                        visual_token_counts=visual_token_counts,
                        labels=labels,
                        use_cache=use_cache,
                        past_key_values=past_key_values,
                        **kwargs,
                    )
                    if aug_result is not None:
                        # Replace BOTH hidden_states and past_key_values
                        # with the augmented re-pass results. The
                        # original cache only holds KVs from the first
                        # ``branch_point`` layers of the un-augmented
                        # prefill; HF generate would then decode
                        # against a stale + length-mismatched cache,
                        # producing degenerate repetitions
                        # ("D\n\nD\n\nD\n\n...").
                        hidden_states, past_key_values = aug_result
                        augmented = True
                        break  # all layers re-ran inside the helper

            # SD-RPN training: early-exit once we've passed the last
            # layer needed by OPL hooks. Post-branch layers + lm_head
            # don't contribute to the BCE loss; running them is dead
            # work. ``i`` is 0-indexed, so ``i >= _skip_after_layer``
            # means we've JUST executed layer ``_skip_after_layer``.
            if _skip_post_branch and i >= _skip_after_layer and not augmented:
                break

        # Stage boundary: charge whatever main-path work happened after the
        # last recorded stage. For a plain single-pass (base / two-stage
        # disabled) run this is the entire prefill. For an SD-RPN BYPASS
        # sample (twig fired but no crop was produced) it is the resume of
        # the source prefill through the remaining layers.
        if _qzt_on:
            if augmented:
                qzt.lap("t_postprocess_ms")
            elif qzt.has("t_src_prefill_ms"):
                qzt.lap("t_src_resume_ms")
            else:
                qzt.lap("t_src_prefill_ms")

        hidden_states = self.norm(hidden_states)

        out = Qwen3_5ModelOutputWithPast(
            last_hidden_state=hidden_states,
            past_key_values=past_key_values,
            twig_hidden_states=twig_hidden_states,
            pre_twig_ctx=pre_twig_ctx,
        )
        return out

    def _update_linear_attn_mask(self, attention_mask, past_key_values):
        """
        NOTE: Left-padding is used for linear attention mask.
        No need for zeroing states when
            1. Cached forward
            2. Attending to all inputs
        """
        linear_attn_mask = attention_mask
        if (past_key_values is not None and past_key_values.has_previous_state()) or (
            attention_mask is not None and torch.all(attention_mask == 1)
        ):
            linear_attn_mask = None
        return linear_attn_mask

    def _maybe_augment_with_roi(
        self,
        rpn_hidden_states,
        inputs_embeds_initial,
        raw_attn_mask,
        position_ids,
        text_position_ids,
        position_embeddings,
        image_grid_thw,
        src_images,
        image_processor,
        encode_image_fn,
        image_token_start: int,
        temp_input_ids,
        pos_id_fn,
        visual_token_mask,
        visual_token_counts,
        labels,
        use_cache,
        past_key_values,
        **layer_kwargs,
    ):
        """SD-RPN 2-stage inference:
        compute Q×K from the last twig layer's gated q_proj/k_proj
        (response token vs image tokens), build a per-sample ROI map,
        crop high-res sub-image patches from ``src_images`` via
        ``get_batched_sub_images_v2``, splice them into
        ``inputs_embeds_initial`` via ``insert_sub_feat_v2``, and replay
        ALL decoder layers on the extended sequence.

        Returns ``(hidden_states, past_key_values)`` on success, where
        ``past_key_values`` is the FRESH cache populated by the
        augmented re-pass. Returns ``None`` if no sample triggered an
        ROI crop (caller falls back to the un-augmented path).
        """
        last_twig = self.twig_layers[-1]
        normed = last_twig.input_layernorm(rpn_hidden_states)
        head_dim = last_twig.self_attn.head_dim
        num_heads = self.config.num_attention_heads
        num_key_value_heads = self.config.num_key_value_heads
        num_kv_groups = num_heads // num_key_value_heads
        B, T_seq = rpn_hidden_states.shape[:2]

        # Qwen3.5 gated q_proj — output is (..., H, 2*d) chunked into
        # (query, gate). ROI scoring uses query only (matches the
        # SD-RPN training BCE block).
        q_full = last_twig.self_attn.q_proj(normed).view(
            B, T_seq, num_heads, head_dim * 2,
        )
        q, _gate = torch.chunk(q_full, 2, dim=-1)
        query_states = q.transpose(1, 2)
        key_states = last_twig.self_attn.k_proj(normed).view(
            B, T_seq, num_key_value_heads, head_dim,
        ).transpose(1, 2)
        if hasattr(last_twig.self_attn, "q_norm"):
            query_states = last_twig.self_attn.q_norm(query_states)
        if hasattr(last_twig.self_attn, "k_norm"):
            key_states = last_twig.self_attn.k_norm(key_states)

        cos, sin = position_embeddings
        # Inference RoPE toggle (``roi_infer_with_rope``, set by the eval
        # wrapper; default True = RoPE'd Q/K). Must match the training-time
        # scoring convention: ``config.roi_score_with_rope=1`` pairs with
        # True; a twig trained without RoPE pairs with False.
        if getattr(self, "roi_infer_with_rope", True):
            query_states, key_states = apply_rotary_pos_emb(query_states, key_states, cos, sin)
        key_states = repeat_kv(key_states, num_kv_groups)

        merge_size = int(getattr(self.config, "spatial_merge_size", 2))

        roi_maps = []
        for sample_idx in range(B):
            if visual_token_mask[sample_idx].sum() == 0:
                roi_maps.append(None)
                continue
            grid_h = int(image_grid_thw[sample_idx, 1].item()) // merge_size
            grid_w = int(image_grid_thw[sample_idx, 2].item()) // merge_size
            key_sample = key_states[sample_idx, :, visual_token_mask[sample_idx], :]
            # Inference: query from the LAST text/response token —
            # response hasn't been generated yet, so we use the last
            # prompt position as the proxy query.
            query_sample = query_states[sample_idx, :, -1:, :]
            attn_scores = torch.matmul(
                query_sample, key_sample.transpose(-2, -1)
            ) / math.sqrt(head_dim)
            roi_map = attn_scores.mean(dim=(0, 1)).view(grid_h, grid_w)
            roi_maps.append(roi_map)

        return self._augment_from_roi_maps(
            roi_maps,
            inputs_embeds_initial=inputs_embeds_initial,
            raw_attn_mask=raw_attn_mask,
            position_ids=position_ids,
            image_grid_thw=image_grid_thw,
            src_images=src_images,
            image_processor=image_processor,
            encode_image_fn=encode_image_fn,
            image_token_start=image_token_start,
            temp_input_ids=temp_input_ids,
            pos_id_fn=pos_id_fn,
            visual_token_counts=visual_token_counts,
            labels=labels,
            use_cache=use_cache,
            **layer_kwargs,
        )

    def _augment_from_roi_maps(
        self,
        roi_maps,
        *,
        inputs_embeds_initial,
        raw_attn_mask,
        position_ids,
        image_grid_thw,
        src_images,
        image_processor,
        encode_image_fn,
        image_token_start: int,
        temp_input_ids,
        pos_id_fn,
        visual_token_counts,
        labels,
        use_cache,
        **layer_kwargs,
    ):
        """Shared tail of the 2-stage path: per-sample heatmaps -> bbox
        crop -> (winsparse) encode -> insert_sub_feat_v2 -> full-layer
        replay with a fresh cache."""
        from qwen_src.mm_utils import (
            get_batched_sub_images_v2,
            insert_sub_feat_v2,
        )

        # Stage boundary: the twig forward + Q.K heatmap that produced
        # ``roi_maps`` is the SD-RPN routing cost.
        _qzt_on = bool(getattr(self, "_qzt_on", False))
        if _qzt_on:
            qzt.lap("t_rpn_ms")

        # Crop high-res sub-images using ROI heatmap + threshold.
        sub_image_features, sub_image_counts, sub_image_grid_thw, \
            roi_mask_list, roi_surrounding_bbox \
            = get_batched_sub_images_v2(
                roi_maps,
                src_images,
                image_processor,
                encode_image_fn,
                image_grid_thw,
                self.roi_conf_thresh,
                img_llm_patch_size=self.img_llm_patch_size,
                dynamic_conf_mode=getattr(self, "dynamic_conf_mode", "fixed"),
                dynamic_conf_kwargs=getattr(self, "dynamic_conf_kwargs", None),
                # Window-sparse SD-RPN encoding (inference-only flag, set
                # via lmms-eval model_args). "off" reproduces the iter-13
                # bbox-crop behavior; "max_ratio" drops background tokens
                # in the ViT at the same crop budget; "token_budget"
                # upscales the bbox crop by sqrt(1/fg_ratio) so the
                # kept-foreground token count matches the baseline budget.
                window_sparse_mode=getattr(self, "window_sparse_mode", "off"),
                window_sparse_dilation=int(getattr(self, "window_sparse_dilation", 1)),
                window_sparse_k_max=float(getattr(self, "window_sparse_k_max", 3.0)),
            )

        # Stage boundary: bbox crop -> processor -> ViT re-encode of the
        # high-res sub-image(s) (incl. window-sparse packing).
        if _qzt_on:
            qzt.lap("t_reencode_ms")

        if not any(c > 0 for c in sub_image_counts):
            return None  # nothing to augment — caller continues main path

        # Splice sub-image features into the pre-layer-0 sequence and
        # rebuild position IDs / attention mask.
        (
            new_hidden_states,
            new_attn_mask,
            _valid_token_mask,
            input_ids_updated,
            _inserted_content_mask,
            new_position_ids,
        ) = insert_sub_feat_v2(
            inputs_embeds_initial,
            sub_image_features,
            sub_image_counts,
            visual_token_counts,
            image_token_start,
            labels,
            raw_attn_mask,
            roi_mask_list,
            temp_input_ids,
            reuse_src_pos=False,
            position_ids=position_ids,
            pos_id_fn=pos_id_fn,
            image_grid_thw=image_grid_thw,
            bbox_grid_thw_list=sub_image_grid_thw,
            surrounding_bbox_list=roi_surrounding_bbox,
            image_token_id=self.image_token_id,
            video_token_id=self.video_token_id,
            mask_roi_bg=bool(getattr(self, "window_sparse_mode", "off") != "off"),
        )

        # Split the returned 4D position_ids back into text + 3D vision,
        # matching the input convention of the main forward.
        if new_position_ids.ndim == 3 and new_position_ids.shape[0] == 4:
            new_text_position_ids = new_position_ids[0]
            new_vision_position_ids = new_position_ids[1:]
        else:
            new_text_position_ids = new_position_ids[0]
            new_vision_position_ids = new_position_ids

        # Recompute masks + rotary embeddings for the augmented seq.
        # Use a fresh KV cache so the replay doesn't reuse stale KVs from
        # the un-augmented first pass.
        new_past_key_values = DynamicCache(config=self.config) if use_cache else None
        new_causal_mask = create_causal_mask(
            config=self.config,
            inputs_embeds=new_hidden_states,
            attention_mask=new_attn_mask,
            past_key_values=new_past_key_values,
            position_ids=new_text_position_ids,
        )
        new_linear_mask = self._update_linear_attn_mask(new_attn_mask, new_past_key_values)
        new_position_embeddings = self.rotary_emb(new_hidden_states, new_vision_position_ids)

        # Fresh ``cache_position`` matching the AUGMENTED sequence
        # length. Without this, ``layer_kwargs`` carries through a stale
        # ``cache_position`` from the outer (un-augmented) forward, the
        # KV cache writes the new keys at wrong slots, and the next
        # decode step sees per-layer caches with the wrong length —
        # triggering an SDPA mask-shape mismatch like
        # ``Target [1, H, 1, 1] vs mask [1, 1, 1, T_aug]`` (#demo
        # qwen3.5 single-image generate() crash).
        new_cache_position = torch.arange(
            0, new_hidden_states.shape[1],
            device=new_hidden_states.device,
        )
        # Strip kwargs that we override below to avoid "got multiple
        # values for keyword argument" errors on decoder_layer call.
        _STRIP = {
            "cache_position", "attention_mask", "position_ids",
            "position_embeddings", "past_key_values", "use_cache",
        }
        layer_kwargs_clean = {
            k: v for k, v in layer_kwargs.items() if k not in _STRIP
        }

        # Stage boundary: feature splice + position/mask/rope rebuild +
        # fresh-cache setup is the two-stage post-processing cost.
        if _qzt_on:
            qzt.lap("t_postprocess_ms")

        # Replay all main-path decoder layers on the augmented sequence.
        for j, decoder_layer in enumerate(self.layers[: self.config.num_hidden_layers]):
            layer_mask = (
                new_linear_mask
                if self.config.layer_types[j] == "linear_attention"
                else new_causal_mask
            )
            new_hidden_states = decoder_layer(
                new_hidden_states,
                position_embeddings=new_position_embeddings,
                attention_mask=layer_mask,
                position_ids=new_text_position_ids,
                past_key_values=new_past_key_values,
                use_cache=use_cache,
                cache_position=new_cache_position,
                **layer_kwargs_clean,
            )

        # Stage boundary: the augmented full-depth re-pass.
        if _qzt_on:
            qzt.lap("t_secondary_prefill_ms")


        # Bookkeeping for the chat-class to record + for next-token decode
        # to use the correct trailing position_id.
        if new_position_ids.ndim == 3:
            try:
                self.last_pos_id = new_position_ids[:, :, -1:]
            except Exception:
                self.last_pos_id = None
        return new_hidden_states, new_past_key_values


@auto_docstring
class Qwen3_5Model(Qwen3_5PreTrainedModel):
    base_model_prefix = "model"
    # Reference: fix gemma3 grad acc #37208
    accepts_loss_kwargs = False
    config: Qwen3_5Config
    _no_split_modules = ["Qwen3_5DecoderLayer", "Qwen3_5VisionBlock"]

    def __init__(self, config):
        super().__init__(config)
        self.visual = Qwen3_5VisionModel._from_config(config.vision_config)
        self.language_model = Qwen3_5TextModel._from_config(config.text_config)
        self.rope_deltas = None  # cache rope_deltas here

        # Initialize weights and apply final processing
        self.post_init()

    def get_input_embeddings(self):
        return self.language_model.get_input_embeddings()

    def set_input_embeddings(self, value):
        self.language_model.set_input_embeddings(value)

    def get_vision_position_ids(
        self,
        start_position: int,
        grid_thw: list[int, int, int] | torch.Tensor,
        temp_merge_size: int = 1,
        spatial_merge_size: int = 1,
        time_interval: int = 1,
        device: str | torch.device | None = None,
    ):
        """
        Compute 3D positional indices for vision tokens derived from a single image or video input.

        The positions are generated from the input grid defined by temporal (T), height (H), and
        width (W) dimensions. Temporal and spatial dimensions can be downscaled according to the
        merge sizes used in the vision backbone. The resulting positions are offset by `start_position`.

        Args:
            start_position (`int`):
                Offset added to all computed positional indices.
            grid_thw (`Sequence[int]` or `torch.Tensor` of shape `(3,)`):
                The (T, H, W) grid representing the feature layout of the current image or video after patch embedding.
            temp_merge_size (`int`, *optional*):
                Factor by which the temporal dimension is reduced in the backbone. The temporal grid size is divided
                by this value. Defaults to 1.
            spatial_merge_size (`int`, *optional*):
                Factor by which the spatial dimensions (H and W) are reduced in the backbone. Both H and W are divided
                by this value. Defaults to 1.
            time_interval (`int`, *optional*):
                Spacing factor applied between consecutive temporal position indices.Defaults to 1.
            device (`str` or `torch.device`, *optional*):
                Device on which the resulting tensor is allocated. If `None`, uses the current default device.

        Returns:
            torch.LongTensor of shape (3, sequence_length):
                Positional indices for temporal, height, and width dimensions,
                flattened into sequence form and offset by `start_position`.
        """
        llm_grid_t, llm_grid_h, llm_grid_w = (
            grid_thw[0].item() // temp_merge_size,
            grid_thw[1].item() // spatial_merge_size,
            grid_thw[2].item() // spatial_merge_size,
        )

        # Add `start_position` after arange for compile
        position_temporal = torch.arange(llm_grid_t, device=device) * time_interval
        position_width = torch.arange(llm_grid_w, device=device) + start_position
        position_height = torch.arange(llm_grid_h, device=device) + start_position

        # Repeat the positions per each grid and per video frame. Repeat patterns are important
        # do not modify without checking values!
        position_width = position_width.repeat(llm_grid_h * llm_grid_t)
        position_height = position_height.repeat_interleave(llm_grid_w).repeat(llm_grid_t)
        # Important: add `start_positions` after applying `time_interval`, order matters
        position_temporal = position_temporal.repeat_interleave(llm_grid_h * llm_grid_w) + start_position
        vision_position_ids = torch.stack([position_temporal, position_height, position_width], dim=0)

        return vision_position_ids

    def get_rope_index(
        self,
        input_ids: torch.LongTensor,
        mm_token_type_ids: torch.IntTensor,
        image_grid_thw: torch.LongTensor | None = None,
        video_grid_thw: torch.LongTensor | None = None,
        attention_mask: torch.Tensor | None = None,
        **kwargs,
    ) -> tuple[torch.Tensor, torch.Tensor]:
        """
        Difference from Qwen2VL/Qwen2.5VL's get_rope_index:
        - Since Qwen3.5 use timestamps to seperate videos, like <t1> <vision_start> <frame1> <vision_end> <t2> <vision_start> <frame2> <vision_end>, the video_grid_thw should also be split too.

        Args:
            input_ids (`torch.LongTensor` of shape `(batch_size, sequence_length)`):
                Indices of input sequence tokens in the vocabulary. Padding will be ignored by default should you provide
                it.
            mm_token_type_ids (`torch.IntTensor` of shape `(batch_size, sequence_length)`):
                Token type ids matching each modality to a different value in the input sequence, i.e. text (0), image (1), video (2).
            image_grid_thw (`torch.LongTensor` of shape `(num_images, 3)`, *optional*):
                The temporal, height and width of feature shape of each image in LLM.
            video_grid_thw (`torch.LongTensor` of shape `(num_videos, 3)`, *optional*):
                The temporal, height and width of feature shape of each video in LLM.
            attention_mask (`torch.Tensor` of shape `(batch_size, sequence_length)`, *optional*):
                Mask to avoid performing attention on padding token indices. Mask values selected in `[0, 1]`:

                - 1 for tokens that are **not masked**,
                - 0 for tokens that are **masked**.

        Returns:
            position_ids (`torch.LongTensor` of shape `(3, batch_size, sequence_length)`)
            mrope_position_deltas (`torch.Tensor` of shape `(batch_size)`)
        """

        # Separate video grid thw into multiple grids because timestamps are used to seperate videos.
        if video_grid_thw is not None:
            video_grid_thw = torch.repeat_interleave(video_grid_thw, video_grid_thw[:, 0], dim=0)
            video_grid_thw[:, 0] = 1
        spatial_merge_size = self.config.vision_config.spatial_merge_size

        mrope_position_deltas = []
        position_ids = torch.zeros(
            3,
            input_ids.shape[0],
            input_ids.shape[1],
            dtype=input_ids.dtype,
            device=input_ids.device,
        )
        grid_iters = {
            1: iter(image_grid_thw) if image_grid_thw is not None else None,
            2: iter(video_grid_thw) if video_grid_thw is not None else None,
        }

        for batch_idx, current_input_ids in enumerate(input_ids):
            input_token_type = mm_token_type_ids[batch_idx]
            if attention_mask is not None:
                current_input_ids = current_input_ids[attention_mask[batch_idx].bool()]
                input_token_type = input_token_type[attention_mask[batch_idx].bool()]

            input_type_group = []
            for key, group in itertools.groupby(enumerate(input_token_type.tolist()), lambda x: x[1]):
                group = list(group)
                start_index = group[0][0]
                end_index = group[-1][0] + 1
                input_type_group.append((key, start_index, end_index))

            current_pos = 0
            llm_pos_ids_list = []
            for modality_type, start_idx, end_idx in input_type_group:
                # text == 0
                if modality_type == 0:
                    text_len = end_idx - start_idx
                    llm_pos_ids_list.append(
                        torch.arange(text_len, device=input_ids.device).view(1, -1).expand(3, -1) + current_pos
                    )
                    current_pos += text_len
                # image == 1, video == 2
                else:
                    grid_thw = next(grid_iters[modality_type])
                    vision_position_ids = self.get_vision_position_ids(
                        current_pos, grid_thw, 1, spatial_merge_size, device=input_ids.device
                    )
                    llm_pos_ids_list.append(vision_position_ids)
                    current_pos += max(grid_thw[1], grid_thw[2]) // spatial_merge_size
            llm_positions = torch.cat(llm_pos_ids_list, dim=1).reshape(3, -1)
            if attention_mask is not None:
                position_ids[:, batch_idx, attention_mask[batch_idx].bool()] = llm_positions.to(position_ids.device)
            else:
                position_ids[:, batch_idx] = llm_positions.to(position_ids.device)
            mrope_position_deltas.append(llm_positions.max() + 1 - len(current_input_ids))
        mrope_position_deltas = torch.tensor(mrope_position_deltas, device=input_ids.device).unsqueeze(1)
        return position_ids, mrope_position_deltas

    @can_return_tuple
    @auto_docstring
    def get_video_features(
        self,
        pixel_values_videos: torch.FloatTensor,
        video_grid_thw: torch.LongTensor | None = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> tuple | BaseModelOutputWithPooling:
        r"""
        pixel_values_videos (`torch.FloatTensor` of shape `(batch_size, num_channels, image_size, image_size)`):
            The tensors corresponding to the input videos.
        video_grid_thw (`torch.LongTensor` of shape `(num_videos, 3)`, *optional*):
            The temporal, height and width of feature shape of each video in LLM.
        """
        # Same implementation as for images
        return self.get_image_features(pixel_values_videos, video_grid_thw, **kwargs)

    @can_return_tuple
    @auto_docstring
    def get_image_features(
        self,
        pixel_values: torch.FloatTensor,
        image_grid_thw: torch.LongTensor | None = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> tuple | BaseModelOutputWithPooling:
        r"""
        pixel_values (`torch.FloatTensor` of shape `(batch_size, num_channels, image_size, image_size)`):
            The tensors corresponding to the input images.
        image_grid_thw (`torch.LongTensor` of shape `(num_images, 3)`, *optional*):
            The temporal, height and width of feature shape of each image in LLM.
        """
        pixel_values = pixel_values.type(self.visual.dtype)
        vision_output: BaseModelOutputWithPooling = self.visual(
            pixel_values, grid_thw=image_grid_thw, return_dict=True, **kwargs
        )
        image_embeds = vision_output.pooler_output
        split_sizes = (image_grid_thw.prod(-1) // self.visual.spatial_merge_size**2).tolist()
        image_embeds = torch.split(image_embeds, split_sizes)
        vision_output.pooler_output = image_embeds

        return vision_output

    def get_placeholder_mask(
        self,
        input_ids: torch.LongTensor,
        inputs_embeds: torch.FloatTensor,
        image_features: torch.FloatTensor | None = None,
        video_features: torch.FloatTensor | None = None,
    ):
        """
        Obtains multimodal placeholder mask from `input_ids` or `inputs_embeds`, and checks that the placeholder token count is
        equal to the length of multimodal features. If the lengths are different, an error is raised.
        """
        if input_ids is None:
            special_image_mask = inputs_embeds == self.get_input_embeddings()(
                torch.tensor(self.config.image_token_id, dtype=torch.long, device=inputs_embeds.device)
            )
            special_image_mask = special_image_mask.all(-1)
            special_video_mask = inputs_embeds == self.get_input_embeddings()(
                torch.tensor(self.config.video_token_id, dtype=torch.long, device=inputs_embeds.device)
            )
            special_video_mask = special_video_mask.all(-1)
        else:
            special_image_mask = input_ids == self.config.image_token_id
            special_video_mask = input_ids == self.config.video_token_id

        n_image_tokens = special_image_mask.sum()
        special_image_mask = special_image_mask.unsqueeze(-1).expand_as(inputs_embeds).to(inputs_embeds.device)
        if image_features is not None:
            torch_compilable_check(
                inputs_embeds[special_image_mask].numel() == image_features.numel(),
                f"Image features and image tokens do not match, tokens: {n_image_tokens}, features: {image_features.shape[0]}",
            )

        n_video_tokens = special_video_mask.sum()
        special_video_mask = special_video_mask.unsqueeze(-1).expand_as(inputs_embeds).to(inputs_embeds.device)
        if video_features is not None:
            torch_compilable_check(
                inputs_embeds[special_video_mask].numel() == video_features.numel(),
                f"Video features and video tokens do not match, tokens: {n_video_tokens}, features: {video_features.shape[0]}",
            )
        return special_image_mask, special_video_mask

    def compute_3d_position_ids(
        self,
        input_ids: torch.Tensor | None,
        inputs_embeds: torch.Tensor | None,
        image_grid_thw: torch.Tensor | None = None,
        video_grid_thw: torch.Tensor | None = None,
        attention_mask: torch.Tensor | None = None,
        past_key_values: torch.Tensor | None = None,
        mm_token_type_ids: torch.IntTensor | None = None,
    ) -> torch.Tensor | None:
        past_key_values_length = 0 if past_key_values is None else past_key_values.get_seq_length()
        has_multimodal = image_grid_thw is not None or video_grid_thw is not None
        if has_multimodal and mm_token_type_ids is None and input_ids is not None:
            raise ValueError(
                "Multimodal data was passed (via `image_grid_thw` or `video_grid_thw`) but `mm_token_type_ids` is "
                "missing. Please pass `mm_token_type_ids` to the model so that multimodal RoPE (M-RoPE) can be "
                "computed correctly. `mm_token_type_ids` is returned by the processor alongside `input_ids`."
            )
        can_compute_mrope = input_ids is not None and mm_token_type_ids is not None and has_multimodal

        if can_compute_mrope and (self.rope_deltas is None or past_key_values_length == 0):
            position_ids, rope_deltas = self.get_rope_index(
                input_ids,
                image_grid_thw=image_grid_thw,
                video_grid_thw=video_grid_thw,
                attention_mask=attention_mask,
                mm_token_type_ids=mm_token_type_ids,
            )
            self.rope_deltas = rope_deltas
        # Use pre-calculated rope-deltas to infer correct 3D position ids during incremental
        # generation (past_key_values_length > 0) or when only inputs_embeds is provided (no input_ids
        # to recompute from). Skip when input_ids is provided without past_key_values to avoid shape
        # mismatches from stale rope_deltas (e.g., training forward pass after generation).
        elif self.rope_deltas is not None and (past_key_values_length > 0 or input_ids is None):
            batch_size, seq_length, _ = inputs_embeds.shape
            if attention_mask is not None:
                position_ids = attention_mask.long().cumsum(-1) - 1
                position_ids = position_ids.masked_fill(attention_mask == 0, 0)
                position_ids = position_ids.view(1, batch_size, -1).repeat(3, 1, 1).to(inputs_embeds.device)
            else:
                position_ids = torch.arange(past_key_values_length, past_key_values_length + seq_length)
                position_ids = position_ids.view(1, 1, -1).expand(3, batch_size, -1).to(inputs_embeds.device)
            delta = self.rope_deltas.repeat_interleave(batch_size // self.rope_deltas.shape[0], dim=0)
            position_ids = position_ids + delta.to(device=inputs_embeds.device)
        else:
            # Can't build correct 3D positions. Let the model infer it
            position_ids = None
        return position_ids

    @auto_docstring
    @can_return_tuple
    def forward(
        self,
        input_ids: torch.LongTensor = None,
        attention_mask: torch.Tensor | None = None,
        position_ids: torch.LongTensor | None = None,
        past_key_values: Cache | None = None,
        inputs_embeds: torch.FloatTensor | None = None,
        pixel_values: torch.Tensor | None = None,
        pixel_values_videos: torch.FloatTensor | None = None,
        image_grid_thw: torch.LongTensor | None = None,
        video_grid_thw: torch.LongTensor | None = None,
        mm_token_type_ids: torch.IntTensor | None = None,
        # ---- SD-RPN inference plumbing forwarded to language_model ----
        src_images: Optional[list] = None,
        image_processor: Optional[Any] = None,
        processor: Optional[Any] = None,
        labels: torch.LongTensor | None = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> tuple | Qwen3_5ModelOutputWithPast:
        r"""
        image_grid_thw (`torch.LongTensor` of shape `(num_images, 3)`, *optional*):
            The temporal, height and width of feature shape of each image in LLM.
        video_grid_thw (`torch.LongTensor` of shape `(num_videos, 3)`, *optional*):
            The temporal, height and width of feature shape of each video in LLM.
        """
        if (input_ids is None) ^ (inputs_embeds is not None):
            raise ValueError("You must specify exactly one of input_ids or inputs_embeds")

        if inputs_embeds is None:
            inputs_embeds = self.get_input_embeddings()(input_ids)

        if pixel_values is not None:
            image_outputs: BaseModelOutputWithPooling = self.get_image_features(
                pixel_values, image_grid_thw, return_dict=True
            )
            image_embeds = image_outputs.pooler_output
            image_embeds = torch.cat(image_embeds, dim=0).to(inputs_embeds.device, inputs_embeds.dtype)
            image_mask, _ = self.get_placeholder_mask(
                input_ids, inputs_embeds=inputs_embeds, image_features=image_embeds
            )
            inputs_embeds = inputs_embeds.masked_scatter(image_mask, image_embeds)

        if pixel_values_videos is not None:
            video_outputs: BaseModelOutputWithPooling = self.get_video_features(
                pixel_values_videos, video_grid_thw, return_dict=True
            )
            video_embeds = video_outputs.pooler_output
            video_embeds = torch.cat(video_embeds, dim=0).to(inputs_embeds.device, inputs_embeds.dtype)
            _, video_mask = self.get_placeholder_mask(
                input_ids, inputs_embeds=inputs_embeds, video_features=video_embeds
            )
            inputs_embeds = inputs_embeds.masked_scatter(video_mask, video_embeds)

        if position_ids is None:
            position_ids = self.compute_3d_position_ids(
                input_ids=input_ids,
                image_grid_thw=image_grid_thw,
                video_grid_thw=video_grid_thw,
                inputs_embeds=inputs_embeds,
                attention_mask=attention_mask,
                past_key_values=past_key_values,
                mm_token_type_ids=mm_token_type_ids,
            )

        # SD-RPN inference plumbing: image_token_id / video_token_id
        # live on the PARENT Qwen3_5Config, not text_config. Read them
        # here and propagate to language_model so its 2-stage gate +
        # visual_token_mask logic can find image tokens.
        image_token_id = getattr(self.config, "image_token_id", None)
        video_token_id = getattr(self.config, "video_token_id", None)
        if image_token_id is not None:
            self.language_model.image_token_id = image_token_id
        if video_token_id is not None:
            self.language_model.video_token_id = video_token_id

        image_token_start = 0
        if input_ids is not None and image_token_id is not None:
            if (input_ids == image_token_id).any():
                image_token_start = int(
                    torch.where(input_ids[0] == image_token_id)[0][0].item()
                )

        # Derive mm_token_type_ids from input_ids on the fly: the SD-RPN
        # augmented re-pass passes a longer raw_ids than the original
        # ``mm_token_type_ids`` covers, so closing over the stale tensor
        # would mismatch in length. 0=text, 1=image, 2=video — match the
        # convention compute_3d_position_ids was given upstream.
        _img_id = getattr(self.config, "image_token_id", None)
        _vid_id = getattr(self.config, "video_token_id", None)

        def _rope_index_wrapper(
            input_ids=None,
            image_grid_thw=None,
            video_grid_thw=None,
            second_per_grid_ts=None,
            attention_mask=None,
        ):
            local_mm_type = None
            if input_ids is not None and _img_id is not None and _vid_id is not None:
                local_mm_type = torch.zeros_like(input_ids, dtype=torch.int32)
                local_mm_type[input_ids == _img_id] = 1
                local_mm_type[input_ids == _vid_id] = 2
            return self.get_rope_index(
                input_ids=input_ids,
                mm_token_type_ids=local_mm_type,
                image_grid_thw=image_grid_thw,
                video_grid_thw=video_grid_thw,
                attention_mask=attention_mask,
            )

        # Wrap ``self.visual`` so the SD-RPN sub-image cropper gets a
        # bare token-feature tensor. ``mm_utils.get_batched_sub_images_v2``
        # expects either a tensor or a (tensor, deepstack) tuple — newer
        # transformers' VisionModel returns a ``BaseModelOutputWithPooling``
        # dataclass instead, which the cropper would store as-is and then
        # crash inside ``torch.cat`` when splicing.
        _visual = self.visual

        def _encode_subimage(pixel_values, grid_thw, keep_token_mask=None):
            # ``keep_token_mask`` (when provided by ``get_batched_sub_images_v2``
            # under the SD-RPN window-encoding inference path) is a bool
            # at LLM-token granularity; the ViT drops the corresponding
            # 2×2 patch blocks before its blocks run.
            out = _visual(
                pixel_values,
                grid_thw=grid_thw,
                keep_token_mask=keep_token_mask,
                return_dict=True,
            )
            return out.pooler_output

        outputs = self.language_model(
            input_ids=None,
            position_ids=position_ids,
            attention_mask=attention_mask,
            past_key_values=past_key_values,
            inputs_embeds=inputs_embeds,
            image_grid_thw=image_grid_thw,
            src_images=src_images,
            image_processor=image_processor,
            encode_image_fn=_encode_subimage,
            image_token_start=image_token_start,
            temp_input_ids=input_ids,
            pos_id_fn=_rope_index_wrapper,
            processor=processor,
            labels=labels,
            **kwargs,
        )

        result = Qwen3_5ModelOutputWithPast(
            **outputs,
            rope_deltas=self.rope_deltas,
        )
        return result


@dataclass
@auto_docstring(
    custom_intro="""
    Base class for Qwen3_5 causal language model (or autoregressive) outputs.
    """
)
class Qwen3_5CausalLMOutputWithPast(ModelOutput):
    r"""
    loss (`torch.FloatTensor` of shape `(1,)`, *optional*, returned when `labels` is provided):
        Language modeling loss (for next-token prediction).
    logits (`torch.FloatTensor` of shape `(batch_size, sequence_length, config.vocab_size)`):
        Prediction scores of the language modeling head (scores for each vocabulary token before SoftMax).
    past_key_values (`Cache`, *optional*, returned when `use_cache=True` is passed or when `config.use_cache=True`):
        It is a [`~cache_utils.Cache`] instance. For more details, see our [kv cache guide](https://huggingface.co/docs/transformers/en/kv_cache).

        Contains pre-computed hidden-states (key and values in the self-attention blocks) that can be used (see
        `past_key_values` input) to speed up sequential decoding.
    rope_deltas (`torch.LongTensor` of shape `(batch_size, )`, *optional*):
        The rope index difference between sequence length and multimodal rope.
    """

    loss: torch.FloatTensor | None = None
    logits: torch.FloatTensor | None = None
    past_key_values: Cache | None = None
    hidden_states: tuple[torch.FloatTensor] | None = None
    attentions: tuple[torch.FloatTensor] | None = None
    rope_deltas: torch.LongTensor | None = None
    # --- region-level GR-REINFORCE (Phase B.1) ---
    # When ``config.return_per_head_score=True`` is set, the forward
    # captures the last-twig per-head response→image score for every
    # sample in the batch. Variable-length across samples (different
    # image grids), so stored as a Python list rather than a tensor.
    #   per_head_scores[b]: tensor of shape (num_heads, k_img_b)
    #   feat_hw[b]:         tuple (Hg_b, Wg_b) such that Hg_b*Wg_b == k_img_b
    per_head_scores: list | None = None
    feat_hw: list | None = None
    # Iter 28 (score_convention=last_prompt_token): expose the policy's
    # twig output so the trainer can recompute per-head scores from the
    # last prompt token (matches SD-RPN inference convention). Declared
    # field rather than dynamic attr so it survives ``**outputs`` spreads
    # / ModelOutput's keys() filtering.
    twig_hidden_states: torch.FloatTensor | None = None
    # Iter 27 (online_p_ref): pre-twig context (hidden_states +
    # position_embeddings + masks + position_ids) so the trainer can
    # run a separate frozen RefTwigModule on identical inputs.
    # MUST be a declared field — when wrapped in DistributedDataParallel,
    # the DDP forward only preserves declared dataclass fields; arbitrary
    # attributes set via ``result.pre_twig_ctx = ...`` post-init get
    # stripped between ``return result`` and the trainer's ``outputs``.
    pre_twig_ctx: dict | None = None


class Qwen3_5ForConditionalGeneration(Qwen3_5PreTrainedModel, GenerationMixin):
    _tied_weights_keys = {"lm_head.weight": "model.language_model.embed_tokens.weight"}
    # Reference: fix gemma3 grad acc #37208
    accepts_loss_kwargs = False
    config: Qwen3_5Config

    def __init__(self, config):
        super().__init__(config)
        self.model = Qwen3_5Model(config)
        self.lm_head = nn.Linear(config.text_config.hidden_size, config.text_config.vocab_size, bias=False)

        self.post_init()

    def get_input_embeddings(self):
        return self.model.get_input_embeddings()

    def set_input_embeddings(self, value):
        self.model.set_input_embeddings(value)

    @auto_docstring
    def get_video_features(
        self,
        pixel_values_videos: torch.FloatTensor,
        video_grid_thw: torch.LongTensor | None = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> tuple | BaseModelOutputWithPooling:
        r"""
        pixel_values_videos (`torch.FloatTensor` of shape `(batch_size, num_channels, image_size, image_size)`):
            The tensors corresponding to the input videos.
        video_grid_thw (`torch.LongTensor` of shape `(num_videos, 3)`, *optional*):
            The temporal, height and width of feature shape of each video in LLM.
        """
        return self.model.get_video_features(
            pixel_values_videos=pixel_values_videos, video_grid_thw=video_grid_thw, **kwargs
        )

    @auto_docstring
    def get_image_features(
        self,
        pixel_values: torch.FloatTensor,
        image_grid_thw: torch.LongTensor | None = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> tuple | BaseModelOutputWithPooling:
        r"""
        pixel_values (`torch.FloatTensor` of shape `(batch_size, num_channels, image_size, image_size)`):
            The tensors corresponding to the input images.
        image_grid_thw (`torch.LongTensor` of shape `(num_images, 3)`, *optional*):
            The temporal, height and width of feature shape of each image in LLM.
        """
        return self.model.get_image_features(pixel_values=pixel_values, image_grid_thw=image_grid_thw, **kwargs)

    @can_return_tuple
    def forward(
        self,
        input_ids: torch.LongTensor = None,
        attention_mask: torch.Tensor | None = None,
        position_ids: torch.LongTensor | None = None,
        past_key_values: Cache | None = None,
        inputs_embeds: torch.FloatTensor | None = None,
        labels: torch.LongTensor | None = None,
        pixel_values: torch.Tensor | None = None,
        pixel_values_videos: torch.FloatTensor | None = None,
        image_grid_thw: torch.LongTensor | None = None,
        video_grid_thw: torch.LongTensor | None = None,
        mm_token_type_ids: torch.IntTensor | None = None,
        logits_to_keep: int | torch.Tensor = 0,
        # SD-RPN extras (optional, only used when enable_twig=True):
        roi_target_map: Optional[torch.LongTensor] = None,
        src_images: Optional[list] = None,
        processor: Optional[Any] = None,
        dataset_modes: Optional[list] = None,
        label_versions: Optional[list] = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> tuple | Qwen3_5CausalLMOutputWithPast:
        r"""
        labels (`torch.LongTensor` of shape `(batch_size, sequence_length)`, *optional*):
            Labels for computing the masked language modeling loss. Indices should either be in `[0, ...,
            config.vocab_size]` or -100 (see `input_ids` docstring). Tokens with indices set to `-100` are ignored
            (masked), the loss is only computed for the tokens with labels in `[0, ..., config.vocab_size]`.
        image_grid_thw (`torch.LongTensor` of shape `(num_images, 3)`, *optional*):
            The temporal, height and width of feature shape of each image in LLM.
        video_grid_thw (`torch.LongTensor` of shape `(num_videos, 3)`, *optional*):
            The temporal, height and width of feature shape of each video in LLM.

        Example:

        ```python
        >>> from transformers import AutoProcessor, Qwen3_5ForConditionalGeneration

        >>> model = Qwen3_5ForConditionalGeneration.from_pretrained("Qwen/Qwen3-VL-8B-Instruct")
        >>> processor = AutoProcessor.from_pretrained("Qwen/Qwen3-VL-8B-Instruct")

        >>> messages = [
            {
                "role": "user",
                "content": [
                    {
                        "type": "image",
                        "image": "https://huggingface.co/datasets/huggingface/documentation-images/resolve/main/pipeline-cat-chonk.jpeg",
                    },
                    {"type": "text", "text": "Describe the image."},
                ],
            }
        ]

        >>> inputs = processor.apply_chat_template(
            messages,
            tokenize=True,
            add_generation_prompt=True,
            return_dict=True,
            return_tensors="pt"
        )

        >>> # Generate
        >>> generated_ids = model.generate(**inputs, max_new_tokens=1024)
        >>> generated_ids_trimmed = [out_ids[len(in_ids) :] for in_ids, out_ids in zip(inputs.input_ids, generated_ids)]
        >>> output_text = processor.batch_decode(generated_ids_trimmed, skip_special_tokens=True, clean_up_tokenization_spaces=False)[0]
        >>> print(output_text)
        ```
        """

        # Online pseudo-label: capture hidden states at every grounding/sink
        # layer in the union of textual+natural head configs, so the ROI
        # loss block can recompute attention without making the main forward
        # eager. Cache lives at ``self._grounding_cache``.
        _online_ctx = None
        if getattr(self.config, "online_pseudo_label", False) and self.training:
            from qwen_src.qwen3_5.online_attention import register_grounding_cache
            from qwen_src.qwen3_5.online_pseudo_label import grounding_layer_set
            family = getattr(self.config, "online_pseudo_label_family", "qwen3_5_9b")
            opl_layers = grounding_layer_set(family)
            _online_ctx = register_grounding_cache(self, opl_layers)
            _online_ctx.__enter__()
        # ``image_processor`` is required by the SD-RPN 2-stage inference
        # path (sub-image cropping). The chat class passes ``processor``;
        # extract its image_processor here so the wrapper / language_model
        # can re-encode high-res ROI crops. Newer transformers (5.6+)
        # store min/max_pixels on ``image_processor.size.{shortest,longest}_edge``
        # rather than as top-level attrs — the mm_utils sub-image cropper
        # still reads ``image_processor.{min,max}_pixels`` directly, so
        # shim them on first access.
        _image_processor = (
            getattr(processor, "image_processor", None)
            if processor is not None
            else None
        )
        if _image_processor is not None and not hasattr(_image_processor, "max_pixels"):
            _size_obj = getattr(_image_processor, "size", None)
            _le = getattr(_size_obj, "longest_edge", None) if _size_obj is not None else None
            _se = getattr(_size_obj, "shortest_edge", None) if _size_obj is not None else None
            if _le is not None:
                _image_processor.max_pixels = int(_le)
            if _se is not None:
                _image_processor.min_pixels = int(_se)
        # Stage timing: stamp the start of the PREFILL forward (first call
        # wins within a sample). Everything from here on — ViT, embedding,
        # LLM layers — is charged to the source prefill until the first
        # in-model lap.
        if qzt.enabled() and not self.training:
            _qzt_slen = None
            if input_ids is not None:
                _qzt_slen = input_ids.shape[1]
            elif inputs_embeds is not None:
                _qzt_slen = inputs_embeds.shape[1]
            if _qzt_slen is not None and _qzt_slen > 1:
                qzt.prefill_t0()
        try:
            outputs = self.model(
                input_ids=input_ids,
                pixel_values=pixel_values,
                pixel_values_videos=pixel_values_videos,
                image_grid_thw=image_grid_thw,
                video_grid_thw=video_grid_thw,
                position_ids=position_ids,
                attention_mask=attention_mask,
                past_key_values=past_key_values,
                inputs_embeds=inputs_embeds,
                mm_token_type_ids=mm_token_type_ids,
                src_images=src_images,
                image_processor=_image_processor,
                processor=processor,
                labels=labels,
                **kwargs,
            )
        finally:
            if _online_ctx is not None:
                _online_ctx.__exit__(None, None, None)

        hidden_states = outputs[0]

        # SD-RPN training: lm_head output is unused (loss is BCE on
        # twig_hidden_states). Skip the big vocab-projection matmul.
        # Same env gate as the post-branch layer skip in TextModel.
        _skip_lm_head = (
            self.training
            and bool(getattr(self.config, "enable_twig", False))
            and int(qz_getenv("SKIP_POST_BRANCH", "1")) == 1
        )
        if _skip_lm_head:
            # Tiny placeholder so HF Trainer's shape checks don't trip.
            B = hidden_states.shape[0]
            _vocab = int(self.config.text_config.vocab_size)
            logits = torch.zeros(
                B, 1, _vocab,
                device=hidden_states.device, dtype=hidden_states.dtype,
            )
        else:
            # Only compute necessary logits, and do not upcast them to float if we are not computing the loss
            slice_indices = slice(-logits_to_keep, None) if isinstance(logits_to_keep, int) else logits_to_keep
            logits = self.lm_head(hidden_states[:, slice_indices, :])

        # Stage timing: end of the prefill forward. Everything after this
        # point until the sample closes is autoregressive decode.
        if qzt.enabled() and not self.training and hidden_states.shape[1] > 1:
            qzt.prefill_end()

        loss = None
        # --- Phase-B.1 hooks ---
        # ``return_per_head_score`` exposes the last-twig per-head response→
        # image score in the output (used by the region-level GR-REINFORCE
        # trainer and by the pre-RL data filter). When set, the BCE
        # supervision branches are skipped and the trainer computes its
        # own loss from the captured per_head_scores.
        return_per_head_score = bool(
            getattr(self.config, "return_per_head_score", False)
        )
        per_head_scores_per_sample: list | None = None
        feat_hw_per_sample: list | None = None
        if return_per_head_score:
            per_head_scores_per_sample = []
            feat_hw_per_sample = []

        if labels is not None and (self.training or return_per_head_score) and getattr(self.config, "enable_twig", False):
            # ---------------- SD-RPN ROI BCE loss ----------------
            text_model = self.model.language_model if hasattr(self.model, "language_model") else self.model
            twig_hidden = getattr(outputs, "twig_hidden_states", None)
            roi_loss_value = None
            if twig_hidden is not None and roi_target_map is not None and text_model.twig_layers is not None:
                B = twig_hidden.shape[0]
                last_twig = text_model.twig_layers[-1]
                # Pre-attention norm + Q/K projection from the last twig
                # layer. We only need Q for response rows × K for image
                # cols → softmax(QK^T / √d) → BCE vs the target mask.
                normed = last_twig.input_layernorm(twig_hidden)
                head_dim = last_twig.self_attn.head_dim
                # Qwen3.5 gated q_proj: output reshapes to (..., H, 2*d) and
                # chunks into (query, gate). Use only the query half here;
                # the gate would be applied post-attention which we don't
                # need for the response→image scoring.
                q_full = last_twig.self_attn.q_proj(normed).view(B, normed.shape[1], -1, head_dim * 2)
                q, _gate = torch.chunk(q_full, 2, dim=-1)
                q = q.transpose(1, 2)
                k = last_twig.self_attn.k_proj(normed).view(B, normed.shape[1], -1, head_dim).transpose(1, 2)
                if hasattr(last_twig.self_attn, "q_norm"):
                    q = last_twig.self_attn.q_norm(q)
                if hasattr(last_twig.self_attn, "k_norm"):
                    k = last_twig.self_attn.k_norm(k)
                # Apply RoPE to match the training-time scoring
                # AND the qwen3_5 inference path (``_maybe_augment_with_roi``).
                # Gated by ``config.roi_score_with_rope`` so legacy iters
                # (iter 13 / 34.x / 38.{a..d,g}) stay no-RoPE while iter
                # 38.e / 38.f opt in.
                if bool(getattr(self.config, "roi_score_with_rope", False)):
                    _pre_twig_ctx = getattr(outputs, "pre_twig_ctx", None)
                    if (_pre_twig_ctx is not None
                            and _pre_twig_ctx.get("position_embeddings") is not None):
                        _cos, _sin = _pre_twig_ctx["position_embeddings"]
                        q, k = apply_rotary_pos_emb(q, k, _cos, _sin)
                # Identify response rows (label != -100) and image cols
                # (input_ids == image_token_id).
                image_token_id = getattr(self.config, "image_token_id", None)
                if image_token_id is not None and input_ids is not None:
                    visual_mask = (input_ids == image_token_id)
                else:
                    visual_mask = None

                # Online pseudo-label: replace per-sample roi_target_map with
                # one freshly computed from response→image attention captured
                # at the grounding layers during the main forward.
                if (
                    getattr(self.config, "online_pseudo_label", False)
                    and visual_mask is not None
                    and labels is not None
                    and image_grid_thw is not None
                    and roi_target_map is not None
                ):
                    from qwen_src.qwen3_5.online_pseudo_label import (
                        online_pseudo_label_for_sample,
                        online_single_region_label_for_sample,
                        PREFIX_IDS_VISUAL_EVIDENCE,
                    )
                    use_single_region = getattr(
                        self.config, "online_single_region", False,
                    )
                    family = getattr(
                        self.config, "online_pseudo_label_family", "qwen3_5_9b",
                    )
                    mode_override_cfg = getattr(
                        self.config, "online_pseudo_label_mode", "auto",
                    )
                    mode_override = (
                        None if mode_override_cfg == "auto" else mode_override_cfg
                    )
                    opl_mode = "aggregated"
                    new_targets = []
                    for sample_idx in range(B):
                        # Default fallback: keep existing target if anything below fails.
                        fallback = (
                            roi_target_map[sample_idx]
                            if isinstance(roi_target_map, list)
                            else roi_target_map[sample_idx]
                        )
                        img_mask = visual_mask[sample_idx]
                        if not img_mask.any():
                            new_targets.append(fallback)
                            continue
                        idxs = img_mask.nonzero(as_tuple=False).squeeze(-1)
                        image_cols = slice(int(idxs[0]), int(idxs[-1]) + 1)
                        lbl = labels[sample_idx]
                        resp_mask = (lbl != -100)
                        if not resp_mask.any():
                            new_targets.append(fallback)
                            continue
                        rdx = resp_mask.nonzero(as_tuple=False).squeeze(-1)
                        response_rows = slice(int(rdx[0]), int(rdx[-1]) + 1)
                        h_patch = int(image_grid_thw[sample_idx][1])
                        w_patch = int(image_grid_thw[sample_idx][2])
                        feat_hw = (h_patch // 2, w_patch // 2)
                        if src_images is not None and sample_idx < len(src_images):
                            src_obj = src_images[sample_idx]
                            if hasattr(src_obj, "size"):
                                original_image_size = src_obj.size
                            else:
                                from PIL import Image as _PILImg
                                original_image_size = _PILImg.open(src_obj).size
                        else:
                            original_image_size = None
                        ds_mode = (
                            dataset_modes[sample_idx]
                            if dataset_modes is not None and sample_idx < len(dataset_modes)
                            else None
                        )
                        # Per-sample label-version dispatch (mixed corpora):
                        # label_versions[i]=='v1' -> mean-over-tokens path,
                        # =='v2' -> single-region. Falls back to the global
                        # config.online_single_region when unspecified.
                        _lv = (
                            label_versions[sample_idx]
                            if label_versions is not None
                            and sample_idx < len(label_versions)
                            else None
                        )
                        if _lv == "v1":
                            sample_use_sr = False
                        elif _lv == "v2":
                            sample_use_sr = True
                        else:
                            sample_use_sr = use_single_region
                        try:
                            if sample_use_sr:
                                # v2 path: per-token single-region union. Skip the
                                # "[Visual Evidence]\n" prefix (5 toks) only when the
                                # response actually starts with it; textvqa / direct
                                # answers (and filtered-out instruction-skips) → skip 0.
                                _resp_ids = (
                                    input_ids[
                                        sample_idx,
                                        response_rows.start:response_rows.start + 5,
                                    ].tolist()
                                    if input_ids is not None else []
                                )
                                _skip = (
                                    5 if _resp_ids == PREFIX_IDS_VISUAL_EVIDENCE
                                    else 0
                                )
                                pseudo = online_single_region_label_for_sample(
                                    model=self,
                                    sample_idx=sample_idx,
                                    response_rows=response_rows,
                                    image_cols=image_cols,
                                    feat_hw=feat_hw,
                                    model_family=family,
                                    mode=(mode_override or ds_mode or "textual"),
                                    skip_leading_tokens=_skip,
                                    extract_smooth_sigma=float(
                                        qz_getenv("SINGLE_REGION_EXTRACT_SIGMA", "0.0")
                                    ),
                                )
                            else:
                                pseudo = online_pseudo_label_for_sample(
                                    model=self,
                                    sample_idx=sample_idx,
                                    response_rows=response_rows,
                                    image_cols=image_cols,
                                    feat_hw=feat_hw,
                                    original_image_size=original_image_size,
                                    model_family=family,
                                    mode_override=mode_override or ds_mode,
                                    pseudo_label_mode=opl_mode,
                                    create_kwargs={
                                        "binary_coff": getattr(
                                            self.config, "roi_binary_coeff", 0.25,
                                        ),
                                        "bg_coff": getattr(self.config, "bg_coff", 0.05),
                                        # mask_known_bg only applies when feat grid is square
                                        # (square-padded inputs). Disable on non-square (dynamic-res).
                                        "mask_known_bg": (
                                            original_image_size is not None
                                            and feat_hw[0] == feat_hw[1]
                                        ),
                                    },
                                )
                        except Exception as exc:
                            print(f"[online_pseudo_label] sample {sample_idx} failed: {exc}")
                            pseudo = None
                        if pseudo is not None and "labels" in pseudo:
                            tgt = torch.tensor(
                                pseudo["labels"], dtype=labels.dtype, device=labels.device,
                            )
                            new_targets.append(tgt)
                        else:
                            new_targets.append(fallback)
                    roi_target_map = new_targets

                mask_score_samples = []
                target_samples = []
                for b in range(B):
                    if visual_mask is None or not visual_mask[b].any():
                        continue
                    img_idx = visual_mask[b].nonzero(as_tuple=False).squeeze(-1)
                    img_slice = slice(int(img_idx[0]), int(img_idx[-1]) + 1)
                    resp_mask = (labels[b] != -100)
                    if not resp_mask.any():
                        continue
                    rdx = resp_mask.nonzero(as_tuple=False).squeeze(-1)
                    resp_slice = slice(int(rdx[0]), int(rdx[-1]) + 1)
                    # Query token set selection: config.roi_score_query_mode ==
                    # "last_prompt" selects the SINGLE position just before the
                    # first response token (the "last prefilling prompt"
                    # position; the SD-RPN inference convention), closing the
                    # train/eval query mismatch; default "response_tokens" =
                    # all response rows, mean over n_q downstream.
                    _q_mode = str(getattr(self.config, "roi_score_query_mode",
                                          "response_tokens"))
                    if _q_mode == "last_prompt":
                        _lp = max(0, int(rdx[0]) - 1)
                        resp_slice = slice(_lp, _lp + 1)
                    # repeat KV heads if GQA
                    n_groups = last_twig.self_attn.num_key_value_groups
                    k_b = k[b:b + 1]
                    if n_groups > 1:
                        k_b = k_b.repeat_interleave(n_groups, dim=1)
                    qb = q[b:b + 1, :, resp_slice, :]
                    kb = k_b[:, :, img_slice, :]
                    score = torch.matmul(qb, kb.transpose(-1, -2)) / math.sqrt(head_dim)
                    # --- Phase-B.1 capture: per-head, mean-over-queries score ---
                    # Captured as raw logits for the trainer (which applies
                    # sigmoid internally).
                    if return_per_head_score:
                        per_head_score_b = score.squeeze(0).mean(dim=1)  # (num_heads, k_img)
                        per_head_scores_per_sample.append(per_head_score_b)
                        # Resolve (Hg, Wg) for the captured score so the
                        # trainer can reshape to a 2D heatmap.
                        spatial_merge = getattr(
                            getattr(self.config, "vision_config", self.config),
                            "spatial_merge_size", 2,
                        )
                        if (
                            image_grid_thw is not None
                            and image_grid_thw.ndim == 2
                            and b < image_grid_thw.shape[0]
                        ):
                            gthw = image_grid_thw[b]
                            h_post = int(gthw[1] // spatial_merge)
                            w_post = int(gthw[2] // spatial_merge)
                            # Sanity-check the product matches.
                            if h_post * w_post != per_head_score_b.shape[1]:
                                # Fallback: assume the grid is already post-merge.
                                h_post = int(gthw[1])
                                w_post = int(gthw[2])
                        else:
                            side = int(per_head_score_b.shape[1] ** 0.5)
                            h_post, w_post = side, side
                        feat_hw_per_sample.append((h_post, w_post))
                        continue  # skip BCE-supervision branches for this sample
                    # mean over heads + queries → [I_img]
                    mask_score = score.mean(dim=1).mean(dim=1).squeeze(0)
                    target_b = roi_target_map[b].to(mask_score.device).float()
                    if target_b.ndim > 1:
                        target_b = target_b.flatten()
                    if target_b.numel() != mask_score.numel():
                        # bilinear-resample target to match the scoring grid.
                        h_t = w_t = int(math.sqrt(target_b.numel()))
                        h_p = w_p = int(math.sqrt(mask_score.numel()))
                        target_b = F.interpolate(
                            target_b.view(1, 1, h_t, w_t),
                            size=(h_p, w_p), mode="nearest",
                        ).view(-1)
                    mask_score_samples.append(mask_score.flatten())
                    target_samples.append(target_b.flatten())
                if mask_score_samples:
                    score_flat = torch.cat(mask_score_samples)
                    tgt_flat = torch.cat(target_samples)
                    valid = tgt_flat != -100
                    if valid.any():
                        roi_loss_value = BCEWithLogitsLoss()(
                            score_flat[valid], tgt_flat[valid].to(score_flat.dtype),
                        )
            if return_per_head_score:
                # Trainer computes its own GR-REINFORCE loss from
                # ``per_head_scores_per_sample``; keep loss=None so the
                # outer compute_loss override has full control.
                loss = None
            elif roi_loss_value is not None:
                loss = roi_loss_value
            elif twig_hidden is not None:
                # No valid samples this microbatch (all -100 targets, or
                # empty mask_score_samples). Route the zero through
                # twig_hidden so backward has a grad_fn — under
                # SKIP_POST_BRANCH=1, logits is a fresh leaf zero tensor
                # with no grad_fn and ``logits.sum()*0.0`` would crash
                # autograd.
                loss = twig_hidden.sum() * 0.0
            else:
                loss = logits.sum() * 0.0
        elif labels is not None:
            loss = self.loss_function(logits=logits, labels=labels, vocab_size=self.config.text_config.vocab_size)

        result = Qwen3_5CausalLMOutputWithPast(
            loss=loss,
            logits=logits,
            past_key_values=outputs.past_key_values,
            hidden_states=outputs.hidden_states,
            attentions=outputs.attentions,
            rope_deltas=outputs.rope_deltas,
            per_head_scores=per_head_scores_per_sample,
            feat_hw=feat_hw_per_sample,
            twig_hidden_states=getattr(outputs, "twig_hidden_states", None),
            pre_twig_ctx=getattr(outputs, "pre_twig_ctx", None),
        )
        return result

    def prepare_inputs_for_generation(
        self,
        input_ids,
        past_key_values=None,
        attention_mask=None,
        inputs_embeds=None,
        position_ids=None,
        use_cache=True,
        pixel_values=None,
        pixel_values_videos=None,
        image_grid_thw=None,
        video_grid_thw=None,
        is_first_iteration=False,
        **kwargs,
    ):
        # Overwritten -- in specific circumstances we don't want to forward image inputs to the model

        model_inputs = super().prepare_inputs_for_generation(
            input_ids,
            past_key_values=past_key_values,
            attention_mask=attention_mask,
            inputs_embeds=inputs_embeds,
            position_ids=position_ids,
            pixel_values=pixel_values,
            pixel_values_videos=pixel_values_videos,
            image_grid_thw=image_grid_thw,
            video_grid_thw=video_grid_thw,
            use_cache=use_cache,
            is_first_iteration=is_first_iteration,
            **kwargs,
        )

        if not is_first_iteration and use_cache:
            model_inputs["pixel_values"] = None
            model_inputs["pixel_values_videos"] = None

        return model_inputs

    def _prepare_position_ids_for_generation(self, inputs_tensor, model_kwargs):
        # Overwritten -- requires 3D position ids

        text_positions = super()._prepare_position_ids_for_generation(inputs_tensor, model_kwargs)

        # Early exit in case we are continuing generation from past kv
        past_length = 0
        if (cache := model_kwargs.get("past_key_values")) is not None:
            past_length = cache.get_seq_length()
        if past_length != 0 and self.model.rope_deltas is not None:
            position_ids = text_positions[None, ...] + self.model.rope_deltas
            return position_ids

        # Otherwise compute 3d position ids for vision tokens and concat with text position ids
        if "input_ids" in model_kwargs and model_kwargs["input_ids"].shape[1] > 0:
            inputs_tensor = model_kwargs["input_ids"]

        is_input_ids = len(inputs_tensor.shape) == 2 and inputs_tensor.dtype in [torch.int, torch.long]
        if (
            is_input_ids
            and model_kwargs.get("mm_token_type_ids") is not None
            and (model_kwargs.get("image_grid_thw") is not None or model_kwargs.get("video_grid_thw") is not None)
        ):
            model_kwargs = {k: v for k, v in model_kwargs.items() if k != "input_ids"}
            vision_positions, rope_deltas = self.model.get_rope_index(inputs_tensor, **model_kwargs)
            self.model.rope_deltas = rope_deltas
        else:
            vision_positions = text_positions.unsqueeze(0).expand(3, -1, -1)
            self.model.rope_deltas = torch.zeros(
                inputs_tensor.shape[0], 1, dtype=torch.long, device=inputs_tensor.device
            )

        # Concatenate "text + vision" positions into [4, bs, seq-len]
        text_positions = text_positions[None, ...]
        position_ids = torch.cat([text_positions, vision_positions], dim=0)

        return position_ids

    def _get_image_nums_and_video_nums(
        self,
        input_ids: torch.LongTensor | None,
        inputs_embeds: torch.Tensor | None = None,
    ) -> tuple[torch.Tensor, torch.Tensor]:
        """
        Get the number of images and videos for each sample to calculate the separation length of the sample tensor.
        These parameters are not passed through the processor to avoid unpredictable impacts from interface modifications.

        Args:
            input_ids (`torch.LongTensor` of shape `(batch_size, sequence_length)`):
                Indices of input sequence tokens in the vocabulary.

        Returns:
            image_nums (`torch.LongTensor` of shape `(batch_size, num_images_sample)`)
            video_nums (`torch.LongTensor` of shape `(batch_size, num_videos_sample)`)
        """
        image_token_id = self.config.image_token_id
        video_token_id = self.config.video_token_id
        vision_start_token_id = self.config.vision_start_token_id

        if inputs_embeds is not None:
            vision_start_mask = (
                inputs_embeds
                == self.get_input_embeddings()(
                    torch.tensor(vision_start_token_id, dtype=torch.long, device=inputs_embeds.device)
                )
            )[..., 0]
            image_mask = (
                inputs_embeds
                == self.get_input_embeddings()(
                    torch.tensor(image_token_id, dtype=torch.long, device=inputs_embeds.device)
                )
            )[..., 0]
            video_mask = (
                inputs_embeds
                == self.get_input_embeddings()(
                    torch.tensor(video_token_id, dtype=torch.long, device=inputs_embeds.device)
                )
            )[..., 0]
        else:
            vision_start_mask = input_ids == vision_start_token_id
            image_mask = input_ids == image_token_id
            video_mask = input_ids == video_token_id

        vision_first_mask = torch.roll(vision_start_mask, shifts=1, dims=1)
        image_nums = torch.sum(vision_first_mask & image_mask, dim=1)
        video_nums = torch.sum(vision_first_mask & video_mask, dim=1)

        return image_nums, video_nums

    def _expand_inputs_for_generation(
        self,
        expand_size: int = 1,
        is_encoder_decoder: bool = False,
        input_ids: torch.LongTensor | None = None,
        **model_kwargs,
    ) -> tuple[torch.LongTensor, dict[str, Any]]:
        # Overwritten -- Qwen3_5 use timestamps and remove second_per_grid_ts
        # Support for expanding tensors without a batch size dimension
        # e.g., pixel_values, image_grid_thw, pixel_values_videos, video_grid_thw
        # pixel_values.shape[0] is sum(seqlen_images for samples)
        # image_grid_thw.shape[0] is sum(num_images for samples)

        if expand_size == 1:
            return input_ids, model_kwargs

        visual_keys = ["pixel_values", "image_grid_thw", "pixel_values_videos", "video_grid_thw"]

        def _expand_dict_for_generation_visual(dict_to_expand):
            image_grid_thw = model_kwargs.get("image_grid_thw", None)
            video_grid_thw = model_kwargs.get("video_grid_thw", None)
            image_nums, video_nums = self._get_image_nums_and_video_nums(
                input_ids, inputs_embeds=model_kwargs.get("inputs_embeds", None)
            )

            # video_nums: (batch_size,)
            # since video_nums is the number of videos in the input dependent on the input_ids(vision_start),
            # but Qwen3_5 append vision_start to each frame of each video, so we need to recover the real video_nums according to video_grid_thw
            if video_grid_thw is not None:
                cumulative_frame_counts = torch.cumsum(video_grid_thw[:, 0], dim=0)
                cumulative_token_video_counts = torch.cumsum(video_nums, dim=0)
                # Find video boundaries in cumulative_frame_counts
                video_boundary_indices = torch.searchsorted(cumulative_frame_counts, cumulative_token_video_counts)
                # example: video_boundary_indices = [3, 5] means video_nums = [4, 2]
                video_nums = torch.diff(torch.cat([-video_boundary_indices.new_ones(1), video_boundary_indices]))

            def _repeat_interleave_samples(x, lengths, repeat_times):
                samples = torch.split(x, lengths)
                repeat_args = [repeat_times] + [1] * (x.dim() - 1)
                result = torch.cat([sample.repeat(*repeat_args) for sample in samples], dim=0)
                return result

            for key in dict_to_expand:
                if key == "pixel_values":
                    # split images into samples
                    samples = torch.split(image_grid_thw, list(image_nums))
                    # compute the sequence length of images for each sample
                    lengths = [torch.prod(sample, dim=1).sum() for sample in samples]
                    dict_to_expand[key] = _repeat_interleave_samples(
                        dict_to_expand[key], lengths=lengths, repeat_times=expand_size
                    )
                elif key == "image_grid_thw":
                    # get the num of images for each sample
                    lengths = list(image_nums)
                    dict_to_expand[key] = _repeat_interleave_samples(
                        dict_to_expand[key], lengths=lengths, repeat_times=expand_size
                    )
                elif key == "pixel_values_videos":
                    samples = torch.split(video_grid_thw, list(video_nums))
                    lengths = [torch.prod(sample, dim=1).sum() for sample in samples]
                    dict_to_expand[key] = _repeat_interleave_samples(
                        dict_to_expand[key], lengths=lengths, repeat_times=expand_size
                    )
                elif key == "video_grid_thw":
                    lengths = list(video_nums)
                    dict_to_expand[key] = _repeat_interleave_samples(
                        dict_to_expand[key], lengths=lengths, repeat_times=expand_size
                    )
            return dict_to_expand

        def _expand_dict_for_generation(dict_to_expand):
            for key in dict_to_expand:
                if key == "position_ids" and dict_to_expand[key].ndim == 3:
                    dict_to_expand[key] = dict_to_expand[key].repeat_interleave(expand_size, dim=1)
                elif (
                    dict_to_expand[key] is not None
                    and isinstance(dict_to_expand[key], torch.Tensor)
                    and key not in visual_keys
                ):
                    dict_to_expand[key] = dict_to_expand[key].repeat_interleave(expand_size, dim=0)
            return dict_to_expand

        model_kwargs = _expand_dict_for_generation_visual(model_kwargs)

        if input_ids is not None:
            input_ids = input_ids.repeat_interleave(expand_size, dim=0)

        model_kwargs = _expand_dict_for_generation(model_kwargs)

        if is_encoder_decoder:
            if model_kwargs.get("encoder_outputs") is None:
                raise ValueError("If `is_encoder_decoder` is True, make sure that `encoder_outputs` is defined.")
            model_kwargs["encoder_outputs"] = _expand_dict_for_generation(model_kwargs["encoder_outputs"])

        return input_ids, model_kwargs

    def load_twig_weights_from_original_model(self, model_args):
        """Initialize twig_layers from the model's own full_attention layers.

        Qwen3.5 alternates linear/full attention so the layer at
        ``twig_K + i`` may not be ``full_attention`` (twig_layers are
        forced to full). For each twig slot we therefore copy weights
        from the nearest full_attention layer at-or-before
        ``twig_K + i``. This still respects the SD-RPN intent (warm-start
        the post-K block) while staying shape-compatible.
        """
        text_model = self.model.language_model if hasattr(self.model, "language_model") else self.model
        cfg_enable = bool(getattr(self.config, "enable_twig", False))
        textmodel_enable = bool(getattr(text_model, "enable_twig", False))
        if not (cfg_enable and textmodel_enable):
            print(
                f"[twig_init] Twig disabled (config={cfg_enable}, text_model={textmodel_enable}). "
                "Skipping twig weight init."
            )
            return
        if not getattr(model_args, "twig_init", True):
            print("[twig_init] twig_init=False — leaving twig_layers at random init.")
            return
        twig_layers = getattr(text_model, "twig_layers", None)
        if twig_layers is None:
            print("[twig_init] twig_layers is None. Skipping.")
            return
        twig_T = int(getattr(text_model, "twig_T", len(twig_layers)))
        twig_K = int(getattr(text_model, "twig_K", 0))
        if len(twig_layers) != twig_T:
            print(f"[twig_init] twig_layers length {len(twig_layers)} != twig_T {twig_T}. Skipping.")
            return

        base_layers = list(getattr(text_model, "layers", []))
        layer_types = getattr(self.config, "layer_types", None)
        if layer_types is None and hasattr(self.config, "text_config"):
            layer_types = getattr(self.config.text_config, "layer_types", None)
        if layer_types is None:
            print("[twig_init] layer_types unavailable; falling back to direct slice.")
            layer_types = ["full_attention"] * len(base_layers)

        def _nearest_full(idx_target: int) -> int:
            """Largest layer idx <= idx_target whose layer_type is full_attention.
            Falls back to the largest full-attention overall if none qualifies."""
            for i in range(min(idx_target, len(layer_types) - 1), -1, -1):
                if layer_types[i] == "full_attention":
                    return i
            for i in range(len(layer_types) - 1, -1, -1):
                if layer_types[i] == "full_attention":
                    return i
            return -1

        for twig_idx in range(twig_T):
            # Convention: twig_K = first replaced layer.
            # twig_layers[i] sources from original layer twig_K + i.
            # For Qwen3.5-9B with K=21, T=3: sources = 21 (linear→fb 19),
            # 22 (linear→fb 19), 23 (full→direct copy).
            target_idx = twig_K + twig_idx
            src_idx = _nearest_full(target_idx)
            if src_idx < 0 or src_idx >= len(base_layers):
                print(f"[twig_init] No full_attention source layer near {target_idx}. Skipping twig {twig_idx}.")
                continue
            try:
                twig_layers[twig_idx].load_state_dict(base_layers[src_idx].state_dict())
                ttype = layer_types[target_idx] if target_idx < len(layer_types) else '?'
                tag = "direct" if src_idx == target_idx else "fallback"
                print(f"[twig_init] twig_layers[{twig_idx}] ← layers[{src_idx}] "
                      f"(target was {target_idx}, type={ttype}, {tag})")
            except Exception as exc:
                raise RuntimeError(
                    f"Failed to copy state_dict for twig_layers[{twig_idx}] "
                    f"from layers[{src_idx}]: {exc}"
                )


